const FILES = {"src/components/UI.js":"import React from 'react';\nimport {\n  View,\n  Text,\n  TextInput,\n  TouchableOpacity,\n  Image,\n  StyleSheet,\n  ScrollView,\n} from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, radius, spacing } from '../theme';\n\n/* ---------- Botão ---------- */\nexport function Button({ title, onPress, variant = 'primary', icon, disabled, style }) {\n  const bg =\n    variant === 'primary'\n      ? colors.primary\n      : variant === 'accent'\n      ? colors.accent\n      : variant === 'danger'\n      ? colors.danger\n      : 'transparent';\n  const textColor = variant === 'accent' ? '#06231D' : colors.text;\n  const border = variant === 'ghost' ? { borderWidth: 1, borderColor: colors.border } : null;\n\n  return (\n    <TouchableOpacity\n      activeOpacity={0.8}\n      onPress={onPress}\n      disabled={disabled}\n      style={[styles.button, { backgroundColor: bg, opacity: disabled ? 0.45 : 1 }, border, style]}\n    >\n      {icon ? <Ionicons name={icon} size={20} color={textColor} style={{ marginRight: 8 }} /> : null}\n      <Text style={[styles.buttonText, { color: textColor }]}>{title}</Text>\n    </TouchableOpacity>\n  );\n}\n\n/* ---------- Cartão ---------- */\nexport function Card({ children, style, onPress, onLongPress }) {\n  if (onPress || onLongPress) {\n    return (\n      <TouchableOpacity\n        activeOpacity={0.85}\n        onPress={onPress}\n        onLongPress={onLongPress}\n        style={[styles.card, style]}\n      >\n        {children}\n      </TouchableOpacity>\n    );\n  }\n  return <View style={[styles.card, style]}>{children}</View>;\n}\n\n/* ---------- Chip de filtro ---------- */\nexport function Chip({ label, active, onPress }) {\n  return (\n    <TouchableOpacity\n      onPress={onPress}\n      activeOpacity={0.8}\n      style={[\n        styles.chip,\n        active && { backgroundColor: colors.primary, borderColor: colors.primary },\n      ]}\n    >\n      <Text style={[styles.chipText, active && { color: colors.text }]}>{label}</Text>\n    </TouchableOpacity>\n  );\n}\n\n/* ---------- Campo de texto com rótulo e erro ---------- */\nexport function Field({ label, error, style, ...props }) {\n  return (\n    <View style={[{ marginBottom: spacing.md }, style]}>\n      {label ? <Text style={styles.label}>{label}</Text> : null}\n      <TextInput\n        placeholderTextColor={colors.muted}\n        {...props}\n        style={[\n          styles.input,\n          props.multiline && { minHeight: 80, textAlignVertical: 'top' },\n          error && { borderColor: colors.danger },\n        ]}\n      />\n      {error ? <Text style={styles.error}>{error}</Text> : null}\n    </View>\n  );\n}\n\n/* ---------- Estado vazio (com imagem) ---------- */\nexport function EmptyState({ title, text, actionLabel, onAction }) {\n  return (\n    <View style={styles.empty}>\n      <Image source={require('../../assets/empty.png')} style={styles.emptyImage} />\n      <Text style={styles.emptyTitle}>{title}</Text>\n      {text ? <Text style={styles.emptyText}>{text}</Text> : null}\n      {actionLabel ? (\n        <Button title={actionLabel} onPress={onAction} style={{ marginTop: spacing.lg }} />\n      ) : null}\n    </View>\n  );\n}\n\n/* ---------- Caixa de estatística ---------- */\nexport function StatBox({ icon, value, label, color = colors.primary }) {\n  return (\n    <View style={styles.statBox}>\n      <Ionicons name={icon} size={20} color={color} />\n      <Text style={styles.statValue}>{value}</Text>\n      <Text style={styles.statLabel}>{label}</Text>\n    </View>\n  );\n}\n\n/* ---------- Título de seção ---------- */\nexport function SectionTitle({ children, style }) {\n  return <Text style={[styles.sectionTitle, style]}>{children}</Text>;\n}\n\n/* ---------- Linha horizontal de chips ---------- */\nexport function ChipRow({ children }) {\n  return (\n    <ScrollView\n      horizontal\n      showsHorizontalScrollIndicator={false}\n      contentContainerStyle={{ paddingHorizontal: spacing.lg, paddingVertical: spacing.sm }}\n      style={{ flexGrow: 0 }}\n    >\n      {children}\n    </ScrollView>\n  );\n}\n\n/* ---------- Botão flutuante ---------- */\nexport function Fab({ icon = 'add', onPress }) {\n  return (\n    <TouchableOpacity activeOpacity={0.85} onPress={onPress} style={styles.fab}>\n      <Ionicons name={icon} size={30} color=\"#fff\" />\n    </TouchableOpacity>\n  );\n}\n\n/* ---------- Botão de ícone pequeno ---------- */\nexport function IconButton({ name, onPress, color = colors.muted, size = 22 }) {\n  return (\n    <TouchableOpacity onPress={onPress} hitSlop={10} style={{ padding: 6 }}>\n      <Ionicons name={name} size={size} color={color} />\n    </TouchableOpacity>\n  );\n}\n\n/* ---------- Seletor numérico (- valor +) ---------- */\nexport function Stepper({ value, onChange, min = 0, max = 999, step = 1, format }) {\n  const dec = () => onChange(Math.max(min, Math.round((value - step) * 100) / 100));\n  const inc = () => onChange(Math.min(max, Math.round((value + step) * 100) / 100));\n  return (\n    <View style={styles.stepper}>\n      <TouchableOpacity onPress={dec} style={styles.stepBtn}>\n        <Ionicons name=\"remove\" size={22} color={colors.text} />\n      </TouchableOpacity>\n      <Text style={styles.stepValue}>{format ? format(value) : value}</Text>\n      <TouchableOpacity onPress={inc} style={styles.stepBtn}>\n        <Ionicons name=\"add\" size={22} color={colors.text} />\n      </TouchableOpacity>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  button: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    justifyContent: 'center',\n    paddingVertical: 14,\n    paddingHorizontal: 20,\n    borderRadius: radius.md,\n  },\n  buttonText: { fontSize: 16, fontWeight: '700' },\n  card: {\n    backgroundColor: colors.card,\n    borderRadius: radius.md,\n    padding: spacing.lg,\n    borderWidth: 1,\n    borderColor: colors.border,\n  },\n  chip: {\n    paddingVertical: 8,\n    paddingHorizontal: 16,\n    borderRadius: 999,\n    borderWidth: 1,\n    borderColor: colors.border,\n    backgroundColor: colors.card,\n    marginRight: spacing.sm,\n    marginBottom: spacing.sm,\n  },\n  chipText: { color: colors.muted, fontWeight: '600' },\n  label: { color: colors.muted, fontSize: 13, marginBottom: 6, fontWeight: '600' },\n  input: {\n    backgroundColor: colors.card,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderRadius: radius.sm,\n    paddingHorizontal: 14,\n    paddingVertical: 12,\n    color: colors.text,\n    fontSize: 16,\n  },\n  error: { color: colors.danger, fontSize: 12, marginTop: 4 },\n  empty: { alignItems: 'center', padding: spacing.xl, marginTop: spacing.xl },\n  emptyImage: { width: 160, height: 160, marginBottom: spacing.lg },\n  emptyTitle: { color: colors.text, fontSize: 20, fontWeight: '700', textAlign: 'center' },\n  emptyText: { color: colors.muted, fontSize: 14, textAlign: 'center', marginTop: 6 },\n  statBox: {\n    flex: 1,\n    backgroundColor: colors.card,\n    borderRadius: radius.md,\n    padding: spacing.md,\n    alignItems: 'center',\n    borderWidth: 1,\n    borderColor: colors.border,\n  },\n  statValue: { color: colors.text, fontSize: 22, fontWeight: '800', marginTop: 6 },\n  statLabel: { color: colors.muted, fontSize: 11, marginTop: 2, textAlign: 'center' },\n  sectionTitle: {\n    color: colors.text,\n    fontSize: 18,\n    fontWeight: '700',\n    marginBottom: spacing.md,\n    marginTop: spacing.lg,\n  },\n  fab: {\n    position: 'absolute',\n    right: 20,\n    bottom: 24,\n    width: 60,\n    height: 60,\n    borderRadius: 30,\n    backgroundColor: colors.primary,\n    alignItems: 'center',\n    justifyContent: 'center',\n    elevation: 6,\n    shadowColor: '#000',\n    shadowOpacity: 0.3,\n    shadowRadius: 6,\n    shadowOffset: { width: 0, height: 3 },\n  },\n  stepper: { flexDirection: 'row', alignItems: 'center' },\n  stepBtn: {\n    width: 40,\n    height: 40,\n    borderRadius: 20,\n    backgroundColor: colors.cardAlt,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  stepValue: {\n    color: colors.text,\n    fontSize: 18,\n    fontWeight: '700',\n    minWidth: 56,\n    textAlign: 'center',\n  },\n});\n","src/context/AppContext.js":"import React, {\n  createContext,\n  useCallback,\n  useContext,\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from 'react';\nimport { ActivityIndicator, Animated, StyleSheet, Text, Vibration, View } from 'react-native';\nimport { useSafeAreaInsets } from 'react-native-safe-area-context';\nimport * as Haptics from 'expo-haptics';\nimport { Ionicons } from '@expo/vector-icons';\nimport { DEFAULT_SETTINGS, initDatabase, loadSettings, saveSetting } from '../db/database';\nimport { colors, radius } from '../theme';\n\nconst AppContext = createContext(null);\n\nexport function useApp() {\n  return useContext(AppContext);\n}\n\nconst safe = (promiseLike) => {\n  try {\n    Promise.resolve(promiseLike).catch(() => {});\n  } catch (e) {\n    /* ignora dispositivos sem suporte */\n  }\n};\n\nexport function AppProvider({ children }) {\n  const insets = useSafeAreaInsets();\n  const [ready, setReady] = useState(false);\n  const [settings, setSettings] = useState(DEFAULT_SETTINGS);\n  const [toast, setToast] = useState(null);\n  const anim = useRef(new Animated.Value(0)).current;\n  const timer = useRef(null);\n\n  // Inicializa banco + carrega configurações\n  useEffect(() => {\n    (async () => {\n      try {\n        await initDatabase();\n        setSettings(await loadSettings());\n      } catch (e) {\n        console.error('Erro ao iniciar o banco', e);\n      }\n      setReady(true);\n    })();\n  }, []);\n\n  const updateSetting = useCallback(async (key, value) => {\n    setSettings((s) => ({ ...s, [key]: value }));\n    await saveSetting(key, value);\n  }, []);\n\n  // Feedback visual: toast animado\n  const showToast = useCallback(\n    (message, type = 'success') => {\n      if (timer.current) clearTimeout(timer.current);\n      setToast({ message, type });\n      Animated.timing(anim, { toValue: 1, duration: 200, useNativeDriver: true }).start();\n      timer.current = setTimeout(() => {\n        Animated.timing(anim, { toValue: 0, duration: 250, useNativeDriver: true }).start(() =>\n          setToast(null)\n        );\n      }, 2300);\n    },\n    [anim]\n  );\n\n  // Feedback tátil (atuador): vibração\n  const feedback = useMemo(\n    () => ({\n      tap: () => settings.haptics && safe(Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)),\n      success: () =>\n        settings.haptics &&\n        safe(Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success)),\n      error: () =>\n        settings.haptics && safe(Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error)),\n      rest: () => settings.haptics && Vibration.vibrate([0, 400, 150, 400]),\n    }),\n    [settings.haptics]\n  );\n\n  const value = useMemo(\n    () => ({ settings, updateSetting, showToast, feedback }),\n    [settings, updateSetting, showToast, feedback]\n  );\n\n  if (!ready) {\n    return (\n      <View style={styles.loading}>\n        <ActivityIndicator size=\"large\" color={colors.primary} />\n      </View>\n    );\n  }\n\n  const isError = toast && toast.type === 'error';\n\n  return (\n    <AppContext.Provider value={value}>\n      {children}\n      {toast ? (\n        <Animated.View\n          pointerEvents=\"none\"\n          style={[\n            styles.toast,\n            {\n              top: insets.top + 8,\n              backgroundColor: isError ? colors.danger : colors.accent,\n              opacity: anim,\n              transform: [\n                { translateY: anim.interpolate({ inputRange: [0, 1], outputRange: [-20, 0] }) },\n              ],\n            },\n          ]}\n        >\n          <Ionicons\n            name={isError ? 'alert-circle' : 'checkmark-circle'}\n            size={20}\n            color={isError ? '#fff' : '#06231D'}\n          />\n          <Text style={[styles.toastText, { color: isError ? '#fff' : '#06231D' }]}>\n            {toast.message}\n          </Text>\n        </Animated.View>\n      ) : null}\n    </AppContext.Provider>\n  );\n}\n\nconst styles = StyleSheet.create({\n  loading: { flex: 1, backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' },\n  toast: {\n    position: 'absolute',\n    left: 16,\n    right: 16,\n    flexDirection: 'row',\n    alignItems: 'center',\n    padding: 14,\n    borderRadius: radius.md,\n    elevation: 10,\n    zIndex: 100,\n  },\n  toastText: { marginLeft: 10, fontWeight: '700', flex: 1 },\n});\n","src/db/database.js":"import * as SQLite from 'expo-sqlite';\nimport { dayKey } from '../utils/format';\n\n/* ------------------------------------------------------------------ *\n *  Conexão + criação das tabelas\n * ------------------------------------------------------------------ */\nlet dbPromise = null;\n\nexport function getDb() {\n  if (!dbPromise) {\n    dbPromise = (async () => {\n      const db = await SQLite.openDatabaseAsync('gymlog.db');\n      await db.execAsync(`\n        PRAGMA journal_mode = WAL;\n        PRAGMA foreign_keys = ON;\n\n        CREATE TABLE IF NOT EXISTS exercises (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          name TEXT NOT NULL,\n          muscle_group TEXT NOT NULL,\n          sets INTEGER NOT NULL DEFAULT 3,\n          reps INTEGER NOT NULL DEFAULT 10,\n          weight REAL NOT NULL DEFAULT 0,\n          notes TEXT,\n          photo TEXT,\n          created_at TEXT NOT NULL\n        );\n\n        CREATE TABLE IF NOT EXISTS workouts (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          started_at TEXT NOT NULL,\n          duration_sec INTEGER NOT NULL DEFAULT 0,\n          notes TEXT\n        );\n\n        CREATE TABLE IF NOT EXISTS workout_sets (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          workout_id INTEGER NOT NULL REFERENCES workouts(id) ON DELETE CASCADE,\n          exercise_id INTEGER,\n          exercise_name TEXT NOT NULL,\n          set_number INTEGER NOT NULL,\n          reps INTEGER NOT NULL,\n          weight REAL NOT NULL DEFAULT 0\n        );\n\n        CREATE TABLE IF NOT EXISTS body_logs (\n          id INTEGER PRIMARY KEY AUTOINCREMENT,\n          date TEXT NOT NULL,\n          weight REAL NOT NULL,\n          note TEXT,\n          photo TEXT\n        );\n\n        CREATE TABLE IF NOT EXISTS settings (\n          key TEXT PRIMARY KEY,\n          value TEXT\n        );\n      `);\n      return db;\n    })();\n  }\n  return dbPromise;\n}\n\n/* ------------------------------------------------------------------ *\n *  Configurações\n * ------------------------------------------------------------------ */\nexport const DEFAULT_SETTINGS = {\n  userName: 'Atleta',\n  weeklyGoal: 3,\n  restSeconds: 60,\n  shake: true,\n  shakeThreshold: 2.0,\n  haptics: true,\n};\n\nexport async function loadSettings() {\n  const db = await getDb();\n  const rows = await db.getAllAsync('SELECT key, value FROM settings');\n  const settings = { ...DEFAULT_SETTINGS };\n  for (const row of rows) {\n    if (!(row.key in DEFAULT_SETTINGS)) continue;\n    const def = DEFAULT_SETTINGS[row.key];\n    if (typeof def === 'boolean') settings[row.key] = row.value === '1';\n    else if (typeof def === 'number') settings[row.key] = Number(row.value);\n    else settings[row.key] = row.value;\n  }\n  return settings;\n}\n\nexport async function saveSetting(key, value) {\n  const db = await getDb();\n  const v = typeof value === 'boolean' ? (value ? '1' : '0') : String(value);\n  await db.runAsync(\n    'INSERT INTO settings (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value',\n    [key, v]\n  );\n}\n\n/* ------------------------------------------------------------------ *\n *  Exercícios (CRUD completo)\n * ------------------------------------------------------------------ */\nconst SEED_EXERCISES = [\n  ['Supino reto', 'Peito', 4, 10, 40, 'Mantenha as escápulas firmes no banco.'],\n  ['Remada curvada', 'Costas', 4, 10, 30, 'Coluna neutra, puxe até o abdômen.'],\n  ['Agachamento livre', 'Pernas', 4, 12, 50, 'Joelhos alinhados com os pés.'],\n  ['Desenvolvimento militar', 'Ombros', 3, 10, 20, ''],\n  ['Rosca direta', 'Braços', 3, 12, 15, 'Sem balançar o tronco.'],\n  ['Abdominal infra', 'Abdômen', 3, 15, 0, ''],\n];\n\nexport async function seedExercises(force = false) {\n  const db = await getDb();\n  if (!force) {\n    const flag = await db.getFirstAsync(\"SELECT value FROM settings WHERE key = 'seeded'\");\n    if (flag) return;\n  }\n  const now = new Date().toISOString();\n  for (const [name, group, sets, reps, weight, notes] of SEED_EXERCISES) {\n    await db.runAsync(\n      'INSERT INTO exercises (name, muscle_group, sets, reps, weight, notes, photo, created_at) VALUES (?, ?, ?, ?, ?, ?, NULL, ?)',\n      [name, group, sets, reps, weight, notes, now]\n    );\n  }\n  await db.runAsync(\n    \"INSERT INTO settings (key, value) VALUES ('seeded', '1') ON CONFLICT(key) DO UPDATE SET value = '1'\"\n  );\n}\n\nexport async function initDatabase() {\n  await getDb();\n  await seedExercises(false);\n}\n\nexport async function listExercises() {\n  const db = await getDb();\n  return db.getAllAsync('SELECT * FROM exercises ORDER BY name COLLATE NOCASE');\n}\n\nexport async function getExercise(id) {\n  const db = await getDb();\n  return db.getFirstAsync('SELECT * FROM exercises WHERE id = ?', [id]);\n}\n\nexport async function getExercisesByIds(ids) {\n  if (!ids || ids.length === 0) return [];\n  const db = await getDb();\n  const rows = await db.getAllAsync(\n    `SELECT * FROM exercises WHERE id IN (${ids.map(() => '?').join(',')})`,\n    ids\n  );\n  // mantém a ordem escolhida pelo usuário\n  return ids.map((id) => rows.find((r) => r.id === id)).filter(Boolean);\n}\n\nexport async function createExercise(e) {\n  const db = await getDb();\n  const res = await db.runAsync(\n    'INSERT INTO exercises (name, muscle_group, sets, reps, weight, notes, photo, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',\n    [e.name, e.muscle_group, e.sets, e.reps, e.weight, e.notes || '', e.photo || null, new Date().toISOString()]\n  );\n  return res.lastInsertRowId;\n}\n\nexport async function updateExercise(id, e) {\n  const db = await getDb();\n  await db.runAsync(\n    'UPDATE exercises SET name = ?, muscle_group = ?, sets = ?, reps = ?, weight = ?, notes = ?, photo = ? WHERE id = ?',\n    [e.name, e.muscle_group, e.sets, e.reps, e.weight, e.notes || '', e.photo || null, id]\n  );\n}\n\nexport async function deleteExercise(id) {\n  const db = await getDb();\n  await db.runAsync('DELETE FROM exercises WHERE id = ?', [id]);\n}\n\n/* ------------------------------------------------------------------ *\n *  Treinos realizados\n * ------------------------------------------------------------------ */\nexport async function saveWorkout({ durationSec, sets }) {\n  const db = await getDb();\n  let workoutId = null;\n  await db.withTransactionAsync(async () => {\n    const startedAt = new Date(Date.now() - durationSec * 1000).toISOString();\n    const res = await db.runAsync(\n      'INSERT INTO workouts (started_at, duration_sec, notes) VALUES (?, ?, ?)',\n      [startedAt, durationSec, '']\n    );\n    workoutId = res.lastInsertRowId;\n    for (const s of sets) {\n      await db.runAsync(\n        'INSERT INTO workout_sets (workout_id, exercise_id, exercise_name, set_number, reps, weight) VALUES (?, ?, ?, ?, ?, ?)',\n        [workoutId, s.exerciseId, s.name, s.setNumber, s.reps, s.weight]\n      );\n    }\n  });\n  return workoutId;\n}\n\nconst WORKOUT_SELECT = `\n  SELECT w.*,\n    COALESCE((SELECT SUM(reps) FROM workout_sets WHERE workout_id = w.id), 0) AS total_reps,\n    COALESCE((SELECT SUM(reps * weight) FROM workout_sets WHERE workout_id = w.id), 0) AS volume,\n    COALESCE((SELECT COUNT(DISTINCT exercise_name) FROM workout_sets WHERE workout_id = w.id), 0) AS exercise_count,\n    COALESCE((SELECT COUNT(*) FROM workout_sets WHERE workout_id = w.id), 0) AS set_count\n  FROM workouts w\n`;\n\nexport async function listWorkouts(limit) {\n  const db = await getDb();\n  const sql = `${WORKOUT_SELECT} ORDER BY w.started_at DESC${limit ? ' LIMIT ' + Number(limit) : ''}`;\n  return db.getAllAsync(sql);\n}\n\nexport async function getWorkout(id) {\n  const db = await getDb();\n  return db.getFirstAsync(`${WORKOUT_SELECT} WHERE w.id = ?`, [id]);\n}\n\nexport async function getWorkoutSets(workoutId) {\n  const db = await getDb();\n  return db.getAllAsync('SELECT * FROM workout_sets WHERE workout_id = ? ORDER BY id ASC', [workoutId]);\n}\n\nexport async function updateWorkoutNotes(id, notes) {\n  const db = await getDb();\n  await db.runAsync('UPDATE workouts SET notes = ? WHERE id = ?', [notes, id]);\n}\n\nexport async function deleteWorkout(id) {\n  const db = await getDb();\n  await db.runAsync('DELETE FROM workouts WHERE id = ?', [id]);\n}\n\n/* ------------------------------------------------------------------ *\n *  Estatísticas para a Home\n * ------------------------------------------------------------------ */\nconst WEEK_LABELS = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];\n\nexport async function getStats() {\n  const workouts = await listWorkouts();\n\n  const weekStart = new Date();\n  weekStart.setHours(0, 0, 0, 0);\n  weekStart.setDate(weekStart.getDate() - ((weekStart.getDay() + 6) % 7)); // segunda-feira\n\n  const weekCount = workouts.filter((w) => new Date(w.started_at) >= weekStart).length;\n  const totalReps = workouts.reduce((acc, w) => acc + w.total_reps, 0);\n  const totalMinutes = Math.round(workouts.reduce((acc, w) => acc + w.duration_sec, 0) / 60);\n\n  const counts = {};\n  workouts.forEach((w) => {\n    const k = dayKey(w.started_at);\n    counts[k] = (counts[k] || 0) + 1;\n  });\n\n  const last7 = [];\n  for (let i = 6; i >= 0; i--) {\n    const d = new Date();\n    d.setDate(d.getDate() - i);\n    last7.push({ label: WEEK_LABELS[d.getDay()], count: counts[dayKey(d)] || 0 });\n  }\n\n  return { weekCount, totalWorkouts: workouts.length, totalReps, totalMinutes, last7 };\n}\n\n/* ------------------------------------------------------------------ *\n *  Registros corporais (CRUD completo)\n * ------------------------------------------------------------------ */\nexport async function listBodyLogs() {\n  const db = await getDb();\n  return db.getAllAsync('SELECT * FROM body_logs ORDER BY date DESC, id DESC');\n}\n\nexport async function createBodyLog({ weight, note, photo }) {\n  const db = await getDb();\n  const res = await db.runAsync(\n    'INSERT INTO body_logs (date, weight, note, photo) VALUES (?, ?, ?, ?)',\n    [new Date().toISOString(), weight, note || '', photo || null]\n  );\n  return res.lastInsertRowId;\n}\n\nexport async function updateBodyLog(id, { weight, note, photo }) {\n  const db = await getDb();\n  await db.runAsync('UPDATE body_logs SET weight = ?, note = ?, photo = ? WHERE id = ?', [\n    weight,\n    note || '',\n    photo || null,\n    id,\n  ]);\n}\n\nexport async function deleteBodyLog(id) {\n  const db = await getDb();\n  await db.runAsync('DELETE FROM body_logs WHERE id = ?', [id]);\n}\n\n/* ------------------------------------------------------------------ *\n *  Resetar tudo\n * ------------------------------------------------------------------ */\nexport async function resetAllData() {\n  const db = await getDb();\n  await db.withTransactionAsync(async () => {\n    await db.runAsync('DELETE FROM workout_sets');\n    await db.runAsync('DELETE FROM workouts');\n    await db.runAsync('DELETE FROM body_logs');\n    await db.runAsync('DELETE FROM exercises');\n  });\n  await seedExercises(true);\n}\n","src/navigation/index.js":"import React from 'react';\nimport { TouchableOpacity } from 'react-native';\nimport { DarkTheme, NavigationContainer } from '@react-navigation/native';\nimport { createNativeStackNavigator } from '@react-navigation/native-stack';\nimport { createBottomTabNavigator } from '@react-navigation/bottom-tabs';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors } from '../theme';\n\nimport HomeScreen from '../screens/HomeScreen';\nimport ExerciseListScreen from '../screens/ExerciseListScreen';\nimport ExerciseFormScreen from '../screens/ExerciseFormScreen';\nimport WorkoutSetupScreen from '../screens/WorkoutSetupScreen';\nimport ActiveWorkoutScreen from '../screens/ActiveWorkoutScreen';\nimport HistoryScreen from '../screens/HistoryScreen';\nimport WorkoutDetailScreen from '../screens/WorkoutDetailScreen';\nimport ProgressScreen from '../screens/ProgressScreen';\nimport SettingsScreen from '../screens/SettingsScreen';\n\nconst Stack = createNativeStackNavigator();\nconst Tab = createBottomTabNavigator();\n\nconst navTheme = {\n  ...DarkTheme,\n  colors: {\n    ...DarkTheme.colors,\n    background: colors.bg,\n    card: colors.card,\n    text: colors.text,\n    border: colors.border,\n    primary: colors.primary,\n  },\n};\n\nconst ICONS = {\n  Home: ['home', 'home-outline'],\n  Exercicios: ['list', 'list-outline'],\n  Treinar: ['play-circle', 'play-circle-outline'],\n  Historico: ['time', 'time-outline'],\n  Progresso: ['trending-up', 'trending-up-outline'],\n};\n\nfunction Tabs() {\n  return (\n    <Tab.Navigator\n      screenOptions={({ route }) => ({\n        headerStyle: { backgroundColor: colors.card },\n        headerTintColor: colors.text,\n        headerTitleStyle: { fontWeight: '800' },\n        tabBarStyle: { backgroundColor: colors.card, borderTopColor: colors.border },\n        tabBarActiveTintColor: colors.primary,\n        tabBarInactiveTintColor: colors.muted,\n        tabBarIcon: ({ focused, color, size }) => (\n          <Ionicons name={ICONS[route.name][focused ? 0 : 1]} size={size} color={color} />\n        ),\n      })}\n    >\n      <Tab.Screen\n        name=\"Home\"\n        component={HomeScreen}\n        options={({ navigation }) => ({\n          title: 'GymLog',\n          tabBarLabel: 'Início',\n          headerRight: () => (\n            <TouchableOpacity onPress={() => navigation.navigate('Configuracoes')} style={{ marginRight: 16 }}>\n              <Ionicons name=\"settings-outline\" size={24} color={colors.text} />\n            </TouchableOpacity>\n          ),\n        })}\n      />\n      <Tab.Screen name=\"Exercicios\" component={ExerciseListScreen} options={{ title: 'Exercícios', tabBarLabel: 'Exercícios' }} />\n      <Tab.Screen name=\"Treinar\" component={WorkoutSetupScreen} options={{ title: 'Treinar', tabBarLabel: 'Treinar' }} />\n      <Tab.Screen name=\"Historico\" component={HistoryScreen} options={{ title: 'Histórico', tabBarLabel: 'Histórico' }} />\n      <Tab.Screen name=\"Progresso\" component={ProgressScreen} options={{ title: 'Meu progresso', tabBarLabel: 'Progresso' }} />\n    </Tab.Navigator>\n  );\n}\n\nexport default function Navigation() {\n  return (\n    <NavigationContainer theme={navTheme}>\n      <Stack.Navigator\n        screenOptions={{\n          headerStyle: { backgroundColor: colors.card },\n          headerTintColor: colors.text,\n          headerTitleStyle: { fontWeight: '800' },\n          contentStyle: { backgroundColor: colors.bg },\n        }}\n      >\n        <Stack.Screen name=\"Tabs\" component={Tabs} options={{ headerShown: false }} />\n        <Stack.Screen name=\"FormExercicio\" component={ExerciseFormScreen} options={{ title: 'Exercício' }} />\n        <Stack.Screen\n          name=\"TreinoAtivo\"\n          component={ActiveWorkoutScreen}\n          options={{ title: 'Treino em andamento', gestureEnabled: false }}\n        />\n        <Stack.Screen name=\"DetalheTreino\" component={WorkoutDetailScreen} options={{ title: 'Detalhes do treino' }} />\n        <Stack.Screen name=\"Configuracoes\" component={SettingsScreen} options={{ title: 'Configurações' }} />\n      </Stack.Navigator>\n    </NavigationContainer>\n  );\n}\n","src/screens/ActiveWorkoutScreen.js":"import React, { useCallback, useEffect, useRef, useState } from 'react';\nimport { ActivityIndicator, Alert, ScrollView, StyleSheet, Text, TouchableOpacity, View } from 'react-native';\nimport { Accelerometer } from 'expo-sensors';\nimport { useKeepAwake } from 'expo-keep-awake';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, radius, spacing } from '../theme';\nimport { Button, Card, Stepper } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { getExercisesByIds, saveWorkout } from '../db/database';\nimport { formatDuration, formatKg, parseNumber } from '../utils/format';\n\nexport default function ActiveWorkoutScreen({ route, navigation }) {\n  useKeepAwake(); // mantém a tela acesa durante o treino\n  const { ids } = route.params;\n  const { settings, showToast, feedback } = useApp();\n\n  const [exercises, setExercises] = useState(null);\n  const [exIndex, setExIndex] = useState(0);\n  const [setNumber, setSetNumber] = useState(1);\n  const [reps, setReps] = useState(0);\n  const [weight, setWeight] = useState(0);\n  const [done, setDone] = useState([]);\n  const [restEnd, setRestEnd] = useState(null);\n  const [now, setNow] = useState(Date.now());\n  const [sensorOk, setSensorOk] = useState(true);\n\n  const startRef = useRef(Date.now());\n  const doneRef = useRef([]);\n  const finishedRef = useRef(false);\n  const lastShake = useRef(0);\n\n  useEffect(() => {\n    doneRef.current = done;\n  }, [done]);\n\n  /* ---------- carregar exercícios ---------- */\n  useEffect(() => {\n    (async () => {\n      const list = await getExercisesByIds(ids);\n      if (list.length === 0) {\n        showToast('Nenhum exercício encontrado', 'error');\n        finishedRef.current = true;\n        navigation.goBack();\n        return;\n      }\n      setExercises(list);\n      setWeight(list[0].weight);\n      startRef.current = Date.now();\n    })();\n  }, [ids, navigation, showToast]);\n\n  /* ---------- relógio (cronômetro + descanso) ---------- */\n  useEffect(() => {\n    const t = setInterval(() => setNow(Date.now()), 500);\n    return () => clearInterval(t);\n  }, []);\n\n  const elapsed = Math.floor((now - startRef.current) / 1000);\n  const restLeft = restEnd ? Math.max(0, Math.ceil((restEnd - now) / 1000)) : 0;\n  const resting = restEnd !== null;\n\n  // fim do descanso -> vibra e avisa\n  useEffect(() => {\n    if (restEnd && now >= restEnd) {\n      setRestEnd(null);\n      feedback.rest();\n      showToast('Descanso finalizado! Próxima série.');\n    }\n  }, [now, restEnd, feedback, showToast]);\n\n  /* ---------- SENSOR: acelerômetro (chacoalhar = +1 repetição) ---------- */\n  useEffect(() => {\n    let sub = null;\n    let cancelled = false;\n    (async () => {\n      const available = await Accelerometer.isAvailableAsync();\n      if (cancelled) return;\n      setSensorOk(available);\n      if (!available || !settings.shake || resting || !exercises) return;\n\n      Accelerometer.setUpdateInterval(80);\n      sub = Accelerometer.addListener(({ x, y, z }) => {\n        const magnitude = Math.sqrt(x * x + y * y + z * z); // em \"g\"; parado ≈ 1\n        const t = Date.now();\n        if (magnitude > settings.shakeThreshold && t - lastShake.current > 700) {\n          lastShake.current = t;\n          setReps((r) => r + 1);\n          feedback.tap();\n        }\n      });\n    })();\n    return () => {\n      cancelled = true;\n      if (sub) sub.remove();\n    };\n  }, [settings.shake, settings.shakeThreshold, resting, exercises, feedback]);\n\n  /* ---------- finalizar e salvar ---------- */\n  const finishWorkout = useCallback(\n    async (list) => {\n      if (list.length === 0) {\n        finishedRef.current = true;\n        showToast('Treino cancelado: nenhuma série registrada', 'error');\n        navigation.goBack();\n        return;\n      }\n      try {\n        const durationSec = Math.max(1, Math.floor((Date.now() - startRef.current) / 1000));\n        const id = await saveWorkout({ durationSec, sets: list });\n        finishedRef.current = true;\n        feedback.success();\n        showToast('Treino salvo! Parabéns 💪');\n        navigation.replace('DetalheTreino', { id });\n      } catch (e) {\n        console.error(e);\n        showToast('Erro ao salvar o treino', 'error');\n      }\n    },\n    [feedback, navigation, showToast]\n  );\n\n  /* ---------- confirmar saída ---------- */\n  useEffect(() => {\n    const unsub = navigation.addListener('beforeRemove', (e) => {\n      if (finishedRef.current || doneRef.current.length === 0) return;\n      e.preventDefault();\n      Alert.alert('Sair do treino?', 'Você já registrou séries neste treino.', [\n        { text: 'Continuar treinando', style: 'cancel' },\n        { text: 'Salvar e sair', onPress: () => finishWorkout(doneRef.current) },\n        {\n          text: 'Descartar',\n          style: 'destructive',\n          onPress: () => {\n            finishedRef.current = true;\n            navigation.dispatch(e.data.action);\n          },\n        },\n      ]);\n    });\n    return unsub;\n  }, [navigation, finishWorkout]);\n\n  if (!exercises) {\n    return (\n      <View style={[styles.container, { alignItems: 'center', justifyContent: 'center' }]}>\n        <ActivityIndicator size=\"large\" color={colors.primary} />\n      </View>\n    );\n  }\n\n  const ex = exercises[exIndex];\n  const isLastExercise = exIndex === exercises.length - 1;\n\n  const goToNextExercise = (list) => {\n    if (isLastExercise) {\n      finishWorkout(list);\n      return;\n    }\n    const next = exercises[exIndex + 1];\n    setExIndex(exIndex + 1);\n    setSetNumber(1);\n    setReps(0);\n    setWeight(next.weight);\n  };\n\n  const completeSet = () => {\n    if (reps <= 0) {\n      feedback.error();\n      showToast('Conte pelo menos 1 repetição', 'error');\n      return;\n    }\n    const entry = { exerciseId: ex.id, name: ex.name, setNumber, reps, weight };\n    const list = [...done, entry];\n    setDone(list);\n    feedback.success();\n    setReps(0);\n\n    if (setNumber < ex.sets) {\n      setSetNumber(setNumber + 1);\n      setRestEnd(Date.now() + settings.restSeconds * 1000);\n    } else if (isLastExercise) {\n      finishWorkout(list);\n    } else {\n      goToNextExercise(list);\n      setRestEnd(Date.now() + settings.restSeconds * 1000);\n    }\n  };\n\n  const skipExercise = () => {\n    Alert.alert('Pular exercício', `Pular \"${ex.name}\"?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: 'Pular', onPress: () => goToNextExercise(done) },\n    ]);\n  };\n\n  const finishNow = () => {\n    Alert.alert('Finalizar treino', 'Deseja encerrar e salvar o treino agora?', [\n      { text: 'Cancelar', style: 'cancel' },\n      { text: 'Finalizar', onPress: () => finishWorkout(done) },\n    ]);\n  };\n\n  const exerciseSets = done.filter((d) => d.exerciseId === ex.id);\n\n  return (\n    <ScrollView style={styles.container} contentContainerStyle={{ padding: spacing.lg, paddingBottom: 50 }}>\n      {/* topo: cronômetro + status do sensor */}\n      <View style={styles.topRow}>\n        <View style={styles.timerPill}>\n          <Ionicons name=\"time-outline\" size={18} color={colors.accent} />\n          <Text style={styles.timerText}>{formatDuration(elapsed)}</Text>\n        </View>\n        <View style={styles.timerPill}>\n          <Ionicons\n            name=\"phone-portrait-outline\"\n            size={18}\n            color={sensorOk && settings.shake ? colors.accent : colors.muted}\n          />\n          <Text style={[styles.timerText, { fontSize: 13 }]}>\n            {!sensorOk ? 'Sem sensor' : settings.shake ? 'Chacoalhe p/ contar' : 'Sensor desligado'}\n          </Text>\n        </View>\n      </View>\n\n      {/* progresso entre exercícios */}\n      <View style={styles.progressRow}>\n        {exercises.map((e, i) => (\n          <View\n            key={e.id}\n            style={[\n              styles.progressDot,\n              i < exIndex && { backgroundColor: colors.accent },\n              i === exIndex && { backgroundColor: colors.primary },\n            ]}\n          />\n        ))}\n      </View>\n\n      <Text style={styles.exIndex}>\n        Exercício {exIndex + 1} de {exercises.length}\n      </Text>\n      <Text style={styles.exName}>{ex.name}</Text>\n      <Text style={styles.exMeta}>\n        {ex.muscle_group} • meta {ex.sets} × {ex.reps}\n      </Text>\n      {ex.notes ? <Text style={styles.notes}>💡 {ex.notes}</Text> : null}\n\n      {resting ? (\n        /* ---------------- DESCANSO ---------------- */\n        <Card style={styles.restCard}>\n          <Text style={styles.restLabel}>Descansando</Text>\n          <Text style={styles.restTime}>{formatDuration(restLeft)}</Text>\n          <Text style={styles.restNext}>\n            Próxima: série {setNumber} de {ex.sets}\n            {setNumber === 1 ? ` — ${ex.name}` : ''}\n          </Text>\n          <View style={styles.restButtons}>\n            <Button\n              title=\"+15s\"\n              variant=\"ghost\"\n              onPress={() => setRestEnd((r) => (r ? r + 15000 : r))}\n              style={{ flex: 1 }}\n            />\n            <View style={{ width: spacing.md }} />\n            <Button title=\"Pular\" variant=\"accent\" onPress={() => setRestEnd(null)} style={{ flex: 1 }} />\n          </View>\n        </Card>\n      ) : (\n        /* ---------------- SÉRIE ATIVA ---------------- */\n        <Card style={{ marginTop: spacing.lg, alignItems: 'center' }}>\n          <Text style={styles.setLabel}>\n            Série {setNumber} de {ex.sets}\n          </Text>\n\n          <View style={styles.repsRow}>\n            <TouchableOpacity\n              onPress={() => {\n                feedback.tap();\n                setReps((r) => Math.max(0, r - 1));\n              }}\n              style={styles.roundBtn}\n            >\n              <Ionicons name=\"remove\" size={30} color={colors.text} />\n            </TouchableOpacity>\n\n            <View style={{ alignItems: 'center', marginHorizontal: spacing.xl }}>\n              <Text style={styles.repsNumber}>{reps}</Text>\n              <Text style={styles.repsLabel}>repetições</Text>\n            </View>\n\n            <TouchableOpacity\n              onPress={() => {\n                feedback.tap();\n                setReps((r) => r + 1);\n              }}\n              style={[styles.roundBtn, { backgroundColor: colors.primary }]}\n            >\n              <Ionicons name=\"add\" size={30} color=\"#fff\" />\n            </TouchableOpacity>\n          </View>\n\n          <Text style={styles.label}>Carga (kg)</Text>\n          <Stepper value={weight} onChange={setWeight} min={0} max={1000} step={2.5} format={formatKg} />\n\n          <Button\n            title=\"Concluir série\"\n            icon=\"checkmark-circle\"\n            variant=\"accent\"\n            onPress={completeSet}\n            style={{ alignSelf: 'stretch', marginTop: spacing.xl }}\n          />\n        </Card>\n      )}\n\n      {/* séries já feitas neste exercício */}\n      {exerciseSets.length > 0 ? (\n        <View style={{ marginTop: spacing.lg }}>\n          <Text style={styles.sectionTitle}>Séries concluídas</Text>\n          {exerciseSets.map((s) => (\n            <View key={`${s.exerciseId}-${s.setNumber}`} style={styles.doneRow}>\n              <Ionicons name=\"checkmark-circle\" size={20} color={colors.accent} />\n              <Text style={styles.doneText}>\n                Série {s.setNumber}: {s.reps} reps × {formatKg(s.weight)} kg\n              </Text>\n            </View>\n          ))}\n        </View>\n      ) : null}\n\n      <View style={{ marginTop: spacing.xl }}>\n        <Button title=\"Pular exercício\" variant=\"ghost\" icon=\"play-skip-forward\" onPress={skipExercise} />\n        <Button\n          title=\"Finalizar treino\"\n          variant=\"danger\"\n          icon=\"stop-circle\"\n          onPress={finishNow}\n          style={{ marginTop: spacing.md }}\n        />\n      </View>\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  topRow: { flexDirection: 'row', justifyContent: 'space-between' },\n  timerPill: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    backgroundColor: colors.card,\n    paddingVertical: 8,\n    paddingHorizontal: 14,\n    borderRadius: 999,\n    borderWidth: 1,\n    borderColor: colors.border,\n  },\n  timerText: { color: colors.text, fontWeight: '800', marginLeft: 8, fontSize: 16 },\n  progressRow: { flexDirection: 'row', marginTop: spacing.lg },\n  progressDot: {\n    flex: 1,\n    height: 6,\n    borderRadius: 3,\n    backgroundColor: colors.cardAlt,\n    marginHorizontal: 2,\n  },\n  exIndex: { color: colors.muted, marginTop: spacing.lg, fontWeight: '600' },\n  exName: { color: colors.text, fontSize: 28, fontWeight: '800', marginTop: 4 },\n  exMeta: { color: colors.accent, fontWeight: '700', marginTop: 4 },\n  notes: { color: colors.muted, marginTop: spacing.sm, fontStyle: 'italic' },\n  setLabel: { color: colors.muted, fontSize: 15, fontWeight: '700', marginBottom: spacing.md },\n  repsRow: { flexDirection: 'row', alignItems: 'center', marginBottom: spacing.xl },\n  roundBtn: {\n    width: 64,\n    height: 64,\n    borderRadius: 32,\n    backgroundColor: colors.cardAlt,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  repsNumber: { color: colors.text, fontSize: 72, fontWeight: '900', lineHeight: 80 },\n  repsLabel: { color: colors.muted, fontWeight: '600' },\n  label: { color: colors.muted, fontSize: 13, fontWeight: '600', marginBottom: 8 },\n  restCard: { marginTop: spacing.lg, alignItems: 'center', borderColor: colors.warning },\n  restLabel: { color: colors.warning, fontWeight: '800', fontSize: 16 },\n  restTime: { color: colors.text, fontSize: 72, fontWeight: '900', marginVertical: spacing.sm },\n  restNext: { color: colors.muted, textAlign: 'center' },\n  restButtons: { flexDirection: 'row', marginTop: spacing.lg, alignSelf: 'stretch' },\n  sectionTitle: { color: colors.text, fontSize: 16, fontWeight: '700', marginBottom: spacing.sm },\n  doneRow: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    backgroundColor: colors.card,\n    padding: spacing.md,\n    borderRadius: radius.sm,\n    marginBottom: 6,\n  },\n  doneText: { color: colors.text, marginLeft: 10, fontWeight: '600' },\n});\n","src/screens/ExerciseFormScreen.js":"import React, { useEffect, useState } from 'react';\nimport { Alert, Image, ScrollView, StyleSheet, Text, TouchableOpacity, View } from 'react-native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, GROUPS, radius, spacing } from '../theme';\nimport { Button, Chip, Field } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { createExercise, deleteExercise, getExercise, updateExercise } from '../db/database';\nimport { chooseImage } from '../utils/images';\nimport { parseNumber } from '../utils/format';\n\nexport default function ExerciseFormScreen({ route, navigation }) {\n  const id = route.params?.id;\n  const editing = !!id;\n  const { showToast, feedback } = useApp();\n\n  const [name, setName] = useState('');\n  const [group, setGroup] = useState(GROUPS[0]);\n  const [sets, setSets] = useState('3');\n  const [reps, setReps] = useState('10');\n  const [weight, setWeight] = useState('0');\n  const [notes, setNotes] = useState('');\n  const [photo, setPhoto] = useState(null);\n  const [errors, setErrors] = useState({});\n  const [saving, setSaving] = useState(false);\n\n  useEffect(() => {\n    navigation.setOptions({ title: editing ? 'Editar exercício' : 'Novo exercício' });\n    if (!editing) return;\n    (async () => {\n      const ex = await getExercise(id);\n      if (!ex) return;\n      setName(ex.name);\n      setGroup(ex.muscle_group);\n      setSets(String(ex.sets));\n      setReps(String(ex.reps));\n      setWeight(String(ex.weight).replace('.', ','));\n      setNotes(ex.notes || '');\n      setPhoto(ex.photo);\n    })();\n  }, [id, editing, navigation]);\n\n  const validate = () => {\n    const e = {};\n    if (name.trim().length < 2) e.name = 'Informe um nome com pelo menos 2 letras.';\n    const s = parseNumber(sets);\n    const r = parseNumber(reps);\n    const w = parseNumber(weight || '0');\n    if (!Number.isInteger(s) || s < 1 || s > 20) e.sets = 'Use um número inteiro de 1 a 20.';\n    if (!Number.isInteger(r) || r < 1 || r > 200) e.reps = 'Use um número inteiro de 1 a 200.';\n    if (Number.isNaN(w) || w < 0 || w > 1000) e.weight = 'Peso inválido (0 a 1000).';\n    setErrors(e);\n    return Object.keys(e).length === 0;\n  };\n\n  const save = async () => {\n    if (!validate()) {\n      feedback.error();\n      showToast('Corrija os campos destacados', 'error');\n      return;\n    }\n    setSaving(true);\n    const data = {\n      name: name.trim(),\n      muscle_group: group,\n      sets: parseNumber(sets),\n      reps: parseNumber(reps),\n      weight: parseNumber(weight || '0'),\n      notes: notes.trim(),\n      photo,\n    };\n    try {\n      if (editing) await updateExercise(id, data);\n      else await createExercise(data);\n      feedback.success();\n      showToast(editing ? 'Exercício atualizado!' : 'Exercício criado!');\n      navigation.goBack();\n    } catch (err) {\n      console.error(err);\n      showToast('Erro ao salvar', 'error');\n      setSaving(false);\n    }\n  };\n\n  const remove = () => {\n    Alert.alert('Remover exercício', `Deseja remover \"${name}\"?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Remover',\n        style: 'destructive',\n        onPress: async () => {\n          await deleteExercise(id);\n          feedback.success();\n          showToast('Exercício removido');\n          navigation.goBack();\n        },\n      },\n    ]);\n  };\n\n  return (\n    <ScrollView\n      style={styles.container}\n      contentContainerStyle={{ padding: spacing.lg, paddingBottom: 60 }}\n      keyboardShouldPersistTaps=\"handled\"\n    >\n      <TouchableOpacity activeOpacity={0.85} onPress={() => chooseImage(setPhoto)} style={styles.photoBox}>\n        {photo ? (\n          <Image source={{ uri: photo }} style={styles.photo} />\n        ) : (\n          <View style={styles.photoEmpty}>\n            <Ionicons name=\"camera-outline\" size={36} color={colors.muted} />\n            <Text style={styles.photoText}>Adicionar foto do exercício</Text>\n          </View>\n        )}\n      </TouchableOpacity>\n      {photo ? (\n        <Button\n          title=\"Remover foto\"\n          variant=\"ghost\"\n          icon=\"close\"\n          onPress={() => setPhoto(null)}\n          style={{ marginBottom: spacing.md }}\n        />\n      ) : null}\n\n      <Field label=\"Nome\" value={name} onChangeText={setName} placeholder=\"Ex.: Supino inclinado\" error={errors.name} />\n\n      <Text style={styles.label}>Grupo muscular</Text>\n      <View style={styles.chips}>\n        {GROUPS.map((g) => (\n          <Chip key={g} label={g} active={group === g} onPress={() => setGroup(g)} />\n        ))}\n      </View>\n\n      <View style={styles.row}>\n        <Field label=\"Séries\" value={sets} onChangeText={setSets} keyboardType=\"number-pad\" style={{ flex: 1 }} error={errors.sets} />\n        <View style={{ width: spacing.md }} />\n        <Field label=\"Repetições\" value={reps} onChangeText={setReps} keyboardType=\"number-pad\" style={{ flex: 1 }} error={errors.reps} />\n        <View style={{ width: spacing.md }} />\n        <Field label=\"Carga (kg)\" value={weight} onChangeText={setWeight} keyboardType=\"decimal-pad\" style={{ flex: 1 }} error={errors.weight} />\n      </View>\n\n      <Field label=\"Observações\" value={notes} onChangeText={setNotes} placeholder=\"Dicas de execução, ajustes da máquina...\" multiline />\n\n      <Button title={editing ? 'Salvar alterações' : 'Criar exercício'} icon=\"checkmark\" onPress={save} disabled={saving} />\n      {editing ? (\n        <Button title=\"Excluir exercício\" icon=\"trash-outline\" variant=\"danger\" onPress={remove} style={{ marginTop: spacing.md }} />\n      ) : null}\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  photoBox: {\n    height: 180,\n    borderRadius: radius.md,\n    overflow: 'hidden',\n    backgroundColor: colors.card,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderStyle: 'dashed',\n    marginBottom: spacing.md,\n  },\n  photo: { width: '100%', height: '100%' },\n  photoEmpty: { flex: 1, alignItems: 'center', justifyContent: 'center' },\n  photoText: { color: colors.muted, marginTop: 8 },\n  label: { color: colors.muted, fontSize: 13, marginBottom: 8, fontWeight: '600' },\n  chips: { flexDirection: 'row', flexWrap: 'wrap', marginBottom: spacing.md },\n  row: { flexDirection: 'row' },\n});\n","src/screens/ExerciseListScreen.js":"import React, { useCallback, useMemo, useState } from 'react';\nimport { Alert, FlatList, Image, StyleSheet, Text, TextInput, View } from 'react-native';\nimport { useFocusEffect } from '@react-navigation/native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, GROUPS, GROUP_ICONS, radius, spacing } from '../theme';\nimport { Card, Chip, ChipRow, EmptyState, Fab, IconButton } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { deleteExercise, listExercises } from '../db/database';\nimport { formatKg } from '../utils/format';\n\nexport default function ExerciseListScreen({ navigation }) {\n  const { showToast, feedback } = useApp();\n  const [items, setItems] = useState([]);\n  const [query, setQuery] = useState('');\n  const [group, setGroup] = useState(null);\n  const [loading, setLoading] = useState(true);\n\n  const load = useCallback(async () => {\n    setItems(await listExercises());\n    setLoading(false);\n  }, []);\n\n  useFocusEffect(\n    useCallback(() => {\n      load();\n    }, [load])\n  );\n\n  const filtered = useMemo(() => {\n    const q = query.trim().toLowerCase();\n    return items.filter(\n      (i) => (!group || i.muscle_group === group) && i.name.toLowerCase().includes(q)\n    );\n  }, [items, group, query]);\n\n  const confirmDelete = (item) => {\n    Alert.alert('Remover exercício', `Deseja remover \"${item.name}\"?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Remover',\n        style: 'destructive',\n        onPress: async () => {\n          await deleteExercise(item.id);\n          feedback.success();\n          showToast('Exercício removido');\n          load();\n        },\n      },\n    ]);\n  };\n\n  const renderItem = ({ item }) => (\n    <Card\n      style={styles.item}\n      onPress={() => navigation.navigate('FormExercicio', { id: item.id })}\n    >\n      {item.photo ? (\n        <Image source={{ uri: item.photo }} style={styles.thumb} />\n      ) : (\n        <View style={[styles.thumb, styles.thumbPlaceholder]}>\n          <Ionicons name={GROUP_ICONS[item.muscle_group] || 'barbell-outline'} size={28} color={colors.primary} />\n        </View>\n      )}\n      <View style={{ flex: 1, marginHorizontal: spacing.md }}>\n        <Text style={styles.name} numberOfLines={1}>\n          {item.name}\n        </Text>\n        <Text style={styles.group}>{item.muscle_group}</Text>\n        <Text style={styles.meta}>\n          {item.sets} × {item.reps}\n          {item.weight > 0 ? `  •  ${formatKg(item.weight)} kg` : '  •  peso corporal'}\n        </Text>\n      </View>\n      <IconButton name=\"trash-outline\" color={colors.danger} onPress={() => confirmDelete(item)} />\n    </Card>\n  );\n\n  return (\n    <View style={styles.container}>\n      <View style={styles.searchBox}>\n        <Ionicons name=\"search\" size={18} color={colors.muted} />\n        <TextInput\n          value={query}\n          onChangeText={setQuery}\n          placeholder=\"Buscar exercício\"\n          placeholderTextColor={colors.muted}\n          style={styles.searchInput}\n        />\n        {query ? <IconButton name=\"close-circle\" size={18} onPress={() => setQuery('')} /> : null}\n      </View>\n\n      <ChipRow>\n        <Chip label=\"Todos\" active={!group} onPress={() => setGroup(null)} />\n        {GROUPS.map((g) => (\n          <Chip key={g} label={g} active={group === g} onPress={() => setGroup(group === g ? null : g)} />\n        ))}\n      </ChipRow>\n\n      <FlatList\n        data={filtered}\n        keyExtractor={(i) => String(i.id)}\n        renderItem={renderItem}\n        contentContainerStyle={{ padding: spacing.lg, paddingBottom: 110 }}\n        ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />}\n        ListEmptyComponent={\n          loading ? null : (\n            <EmptyState\n              title={items.length === 0 ? 'Nenhum exercício' : 'Nada encontrado'}\n              text={\n                items.length === 0\n                  ? 'Cadastre seu primeiro exercício para montar seus treinos.'\n                  : 'Tente outro nome ou grupo muscular.'\n              }\n              actionLabel={items.length === 0 ? 'Novo exercício' : undefined}\n              onAction={() => navigation.navigate('FormExercicio')}\n            />\n          )\n        }\n      />\n\n      <Fab onPress={() => navigation.navigate('FormExercicio')} />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  searchBox: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    backgroundColor: colors.card,\n    borderRadius: radius.md,\n    marginHorizontal: spacing.lg,\n    marginTop: spacing.md,\n    paddingHorizontal: 14,\n    borderWidth: 1,\n    borderColor: colors.border,\n  },\n  searchInput: { flex: 1, color: colors.text, paddingVertical: 12, marginLeft: 8, fontSize: 16 },\n  item: { flexDirection: 'row', alignItems: 'center', padding: spacing.md },\n  thumb: { width: 64, height: 64, borderRadius: radius.sm },\n  thumbPlaceholder: {\n    backgroundColor: colors.cardAlt,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  name: { color: colors.text, fontSize: 16, fontWeight: '700' },\n  group: { color: colors.accent, fontSize: 12, fontWeight: '700', marginTop: 2 },\n  meta: { color: colors.muted, fontSize: 13, marginTop: 4 },\n});\n","src/screens/HistoryScreen.js":"import React, { useCallback, useState } from 'react';\nimport { Alert, FlatList, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect } from '@react-navigation/native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, spacing } from '../theme';\nimport { Card, EmptyState, IconButton } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { deleteWorkout, listWorkouts } from '../db/database';\nimport { formatDateTime, formatDuration, formatKg } from '../utils/format';\n\nexport default function HistoryScreen({ navigation }) {\n  const { showToast, feedback } = useApp();\n  const [items, setItems] = useState([]);\n  const [loading, setLoading] = useState(true);\n\n  const load = useCallback(async () => {\n    setItems(await listWorkouts());\n    setLoading(false);\n  }, []);\n\n  useFocusEffect(\n    useCallback(() => {\n      load();\n    }, [load])\n  );\n\n  const confirmDelete = (w) => {\n    Alert.alert('Excluir treino', `Excluir o treino de ${formatDateTime(w.started_at)}?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Excluir',\n        style: 'destructive',\n        onPress: async () => {\n          await deleteWorkout(w.id);\n          feedback.success();\n          showToast('Treino excluído');\n          load();\n        },\n      },\n    ]);\n  };\n\n  return (\n    <View style={styles.container}>\n      <FlatList\n        data={items}\n        keyExtractor={(i) => String(i.id)}\n        contentContainerStyle={{ padding: spacing.lg, paddingBottom: 40 }}\n        ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />}\n        ListEmptyComponent={\n          loading ? null : (\n            <EmptyState\n              title=\"Histórico vazio\"\n              text=\"Quando você finalizar um treino, ele aparecerá aqui.\"\n              actionLabel=\"Iniciar treino\"\n              onAction={() => navigation.navigate('Treinar')}\n            />\n          )\n        }\n        renderItem={({ item }) => (\n          <Card onPress={() => navigation.navigate('DetalheTreino', { id: item.id })}>\n            <View style={styles.row}>\n              <View style={styles.icon}>\n                <Ionicons name=\"barbell\" size={24} color={colors.primary} />\n              </View>\n              <View style={{ flex: 1, marginLeft: spacing.md }}>\n                <Text style={styles.date}>{formatDateTime(item.started_at)}</Text>\n                <Text style={styles.meta}>\n                  {item.exercise_count} exercício(s) • {item.set_count} série(s)\n                </Text>\n                <Text style={styles.meta}>\n                  {item.total_reps} reps • {formatKg(item.volume)} kg de volume •{' '}\n                  {formatDuration(item.duration_sec)}\n                </Text>\n                {item.notes ? (\n                  <Text style={styles.note} numberOfLines={1}>\n                    📝 {item.notes}\n                  </Text>\n                ) : null}\n              </View>\n              <IconButton name=\"trash-outline\" color={colors.danger} onPress={() => confirmDelete(item)} />\n            </View>\n          </Card>\n        )}\n      />\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  row: { flexDirection: 'row', alignItems: 'center' },\n  icon: {\n    width: 48,\n    height: 48,\n    borderRadius: 24,\n    backgroundColor: colors.cardAlt,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  date: { color: colors.text, fontSize: 16, fontWeight: '700', marginBottom: 4 },\n  meta: { color: colors.muted, fontSize: 13, marginTop: 1 },\n  note: { color: colors.accent, fontSize: 13, marginTop: 4 },\n});\n","src/screens/HomeScreen.js":"import React, { useCallback, useState } from 'react';\nimport { ImageBackground, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect } from '@react-navigation/native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, radius, spacing } from '../theme';\nimport { Button, Card, SectionTitle, StatBox } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { getStats, listWorkouts } from '../db/database';\nimport { formatDateTime, formatDuration, greeting } from '../utils/format';\n\nexport default function HomeScreen({ navigation }) {\n  const { settings } = useApp();\n  const [stats, setStats] = useState(null);\n  const [last, setLast] = useState(null);\n\n  useFocusEffect(\n    useCallback(() => {\n      let active = true;\n      (async () => {\n        const s = await getStats();\n        const w = await listWorkouts(1);\n        if (active) {\n          setStats(s);\n          setLast(w[0] || null);\n        }\n      })();\n      return () => {\n        active = false;\n      };\n    }, [])\n  );\n\n  const goal = Math.max(1, settings.weeklyGoal);\n  const weekCount = stats ? stats.weekCount : 0;\n  const progress = Math.min(1, weekCount / goal);\n  const maxBar = stats ? Math.max(1, ...stats.last7.map((d) => d.count)) : 1;\n\n  return (\n    <ScrollView\n      style={styles.container}\n      contentContainerStyle={{ padding: spacing.lg, paddingBottom: 40 }}\n    >\n      <ImageBackground\n        source={require('../../assets/banner.png')}\n        style={styles.banner}\n        imageStyle={{ borderRadius: radius.lg }}\n      >\n        <Text style={styles.hello}>\n          {greeting()}, {settings.userName}!\n        </Text>\n        <Text style={styles.sub}>Pronto para superar o treino de ontem?</Text>\n      </ImageBackground>\n\n      <Button\n        title=\"Iniciar treino\"\n        icon=\"play\"\n        variant=\"accent\"\n        onPress={() => navigation.navigate('Treinar')}\n        style={{ marginTop: spacing.lg }}\n      />\n\n      <SectionTitle>Meta da semana</SectionTitle>\n      <Card>\n        <View style={styles.rowBetween}>\n          <Text style={styles.goalText}>\n            {weekCount} de {goal} treinos\n          </Text>\n          <Text style={[styles.goalText, { color: colors.accent }]}>\n            {Math.round(progress * 100)}%\n          </Text>\n        </View>\n        <View style={styles.track}>\n          <View style={[styles.fill, { width: `${progress * 100}%` }]} />\n        </View>\n        {progress >= 1 ? (\n          <Text style={styles.congrats}>🎉 Meta batida! Continue assim.</Text>\n        ) : (\n          <Text style={styles.muted}>\n            Faltam {goal - weekCount} treino(s) para bater a meta.\n          </Text>\n        )}\n      </Card>\n\n      <SectionTitle>Resumo geral</SectionTitle>\n      <View style={styles.row}>\n        <StatBox icon=\"trophy-outline\" value={stats ? stats.totalWorkouts : 0} label=\"Treinos\" color={colors.warning} />\n        <View style={{ width: spacing.sm }} />\n        <StatBox icon=\"repeat-outline\" value={stats ? stats.totalReps : 0} label=\"Repetições\" color={colors.primary} />\n        <View style={{ width: spacing.sm }} />\n        <StatBox icon=\"time-outline\" value={stats ? stats.totalMinutes : 0} label=\"Minutos\" color={colors.accent} />\n      </View>\n\n      <SectionTitle>Últimos 7 dias</SectionTitle>\n      <Card>\n        <View style={styles.chart}>\n          {(stats ? stats.last7 : []).map((d, i) => (\n            <View key={i} style={styles.barCol}>\n              <View style={styles.barTrack}>\n                <View\n                  style={[\n                    styles.bar,\n                    {\n                      height: `${(d.count / maxBar) * 100}%`,\n                      backgroundColor: d.count > 0 ? colors.primary : 'transparent',\n                    },\n                  ]}\n                />\n              </View>\n              <Text style={styles.barLabel}>{d.label}</Text>\n            </View>\n          ))}\n        </View>\n      </Card>\n\n      <SectionTitle>Último treino</SectionTitle>\n      {last ? (\n        <Card onPress={() => navigation.navigate('DetalheTreino', { id: last.id })}>\n          <View style={styles.rowBetween}>\n            <View style={{ flex: 1 }}>\n              <Text style={styles.lastTitle}>{formatDateTime(last.started_at)}</Text>\n              <Text style={styles.muted}>\n                {last.exercise_count} exercício(s) • {last.total_reps} reps •{' '}\n                {formatDuration(last.duration_sec)}\n              </Text>\n            </View>\n            <Ionicons name=\"chevron-forward\" size={22} color={colors.muted} />\n          </View>\n        </Card>\n      ) : (\n        <Card>\n          <Text style={styles.muted}>Você ainda não registrou nenhum treino.</Text>\n        </Card>\n      )}\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  banner: { height: 160, justifyContent: 'flex-end', padding: spacing.lg },\n  hello: { color: '#fff', fontSize: 24, fontWeight: '800' },\n  sub: { color: 'rgba(255,255,255,0.9)', marginTop: 4 },\n  row: { flexDirection: 'row' },\n  rowBetween: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },\n  goalText: { color: colors.text, fontSize: 16, fontWeight: '700' },\n  track: {\n    height: 10,\n    backgroundColor: colors.cardAlt,\n    borderRadius: 5,\n    marginVertical: spacing.md,\n    overflow: 'hidden',\n  },\n  fill: { height: '100%', backgroundColor: colors.accent, borderRadius: 5 },\n  muted: { color: colors.muted, fontSize: 13 },\n  congrats: { color: colors.accent, fontWeight: '700' },\n  chart: { flexDirection: 'row', justifyContent: 'space-between', height: 120 },\n  barCol: { flex: 1, alignItems: 'center' },\n  barTrack: {\n    flex: 1,\n    width: 18,\n    backgroundColor: colors.cardAlt,\n    borderRadius: 6,\n    justifyContent: 'flex-end',\n    overflow: 'hidden',\n  },\n  bar: { width: '100%', borderRadius: 6 },\n  barLabel: { color: colors.muted, fontSize: 12, marginTop: 6, fontWeight: '600' },\n  lastTitle: { color: colors.text, fontSize: 16, fontWeight: '700', marginBottom: 4 },\n});\n","src/screens/ProgressScreen.js":"import React, { useCallback, useState } from 'react';\nimport {\n  Alert,\n  FlatList,\n  Image,\n  KeyboardAvoidingView,\n  Modal,\n  Platform,\n  ScrollView,\n  StyleSheet,\n  Text,\n  TouchableOpacity,\n  View,\n} from 'react-native';\nimport { useFocusEffect } from '@react-navigation/native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, radius, spacing } from '../theme';\nimport { Button, Card, EmptyState, Fab, Field, IconButton } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { createBodyLog, deleteBodyLog, listBodyLogs, updateBodyLog } from '../db/database';\nimport { chooseImage } from '../utils/images';\nimport { formatDate, formatKg, parseNumber } from '../utils/format';\n\nexport default function ProgressScreen() {\n  const { showToast, feedback } = useApp();\n  const [logs, setLogs] = useState([]);\n  const [loading, setLoading] = useState(true);\n\n  // estado do modal (formulário)\n  const [modalOpen, setModalOpen] = useState(false);\n  const [editingId, setEditingId] = useState(null);\n  const [weight, setWeight] = useState('');\n  const [note, setNote] = useState('');\n  const [photo, setPhoto] = useState(null);\n  const [error, setError] = useState('');\n\n  const load = useCallback(async () => {\n    setLogs(await listBodyLogs());\n    setLoading(false);\n  }, []);\n\n  useFocusEffect(\n    useCallback(() => {\n      load();\n    }, [load])\n  );\n\n  const openNew = () => {\n    setEditingId(null);\n    setWeight('');\n    setNote('');\n    setPhoto(null);\n    setError('');\n    setModalOpen(true);\n  };\n\n  const openEdit = (log) => {\n    setEditingId(log.id);\n    setWeight(String(log.weight).replace('.', ','));\n    setNote(log.note || '');\n    setPhoto(log.photo);\n    setError('');\n    setModalOpen(true);\n  };\n\n  const save = async () => {\n    const w = parseNumber(weight);\n    if (Number.isNaN(w) || w < 20 || w > 400) {\n      setError('Informe um peso válido entre 20 e 400 kg.');\n      feedback.error();\n      return;\n    }\n    try {\n      if (editingId) await updateBodyLog(editingId, { weight: w, note: note.trim(), photo });\n      else await createBodyLog({ weight: w, note: note.trim(), photo });\n      feedback.success();\n      showToast(editingId ? 'Registro atualizado!' : 'Registro adicionado!');\n      setModalOpen(false);\n      load();\n    } catch (e) {\n      console.error(e);\n      showToast('Erro ao salvar', 'error');\n    }\n  };\n\n  const confirmDelete = (log) => {\n    Alert.alert('Excluir registro', `Excluir o registro de ${formatDate(log.date)}?`, [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Excluir',\n        style: 'destructive',\n        onPress: async () => {\n          await deleteBodyLog(log.id);\n          feedback.success();\n          showToast('Registro excluído');\n          load();\n        },\n      },\n    ]);\n  };\n\n  /* ---------- gráfico: últimos 8 registros ---------- */\n  const chartData = logs.slice(0, 8).reverse();\n  const weights = chartData.map((l) => l.weight);\n  const minW = Math.min(...weights);\n  const maxW = Math.max(...weights);\n  const range = maxW - minW || 1;\n\n  const first = logs.length > 0 ? logs[logs.length - 1].weight : 0;\n  const latest = logs.length > 0 ? logs[0].weight : 0;\n  const diff = latest - first;\n\n  const Header = (\n    <View>\n      {logs.length > 0 ? (\n        <>\n          <View style={styles.summaryRow}>\n            <Card style={styles.summaryCard}>\n              <Text style={styles.summaryLabel}>Peso atual</Text>\n              <Text style={styles.summaryValue}>{formatKg(latest)} kg</Text>\n            </Card>\n            <View style={{ width: spacing.sm }} />\n            <Card style={styles.summaryCard}>\n              <Text style={styles.summaryLabel}>Variação total</Text>\n              <Text\n                style={[\n                  styles.summaryValue,\n                  { color: diff === 0 ? colors.text : diff < 0 ? colors.accent : colors.warning },\n                ]}\n              >\n                {diff > 0 ? '+' : ''}\n                {formatKg(Math.round(diff * 10) / 10)} kg\n              </Text>\n            </Card>\n          </View>\n\n          <Card style={{ marginTop: spacing.md }}>\n            <Text style={styles.chartTitle}>Evolução do peso</Text>\n            <View style={styles.chart}>\n              {chartData.map((l) => {\n                const h = 24 + ((l.weight - minW) / range) * 96;\n                return (\n                  <View key={l.id} style={styles.barCol}>\n                    <Text style={styles.barValue}>{formatKg(l.weight)}</Text>\n                    <View style={[styles.bar, { height: h }]} />\n                    <Text style={styles.barLabel}>{formatDate(l.date).slice(0, 5)}</Text>\n                  </View>\n                );\n              })}\n            </View>\n          </Card>\n\n          <Text style={styles.listTitle}>Registros</Text>\n        </>\n      ) : null}\n    </View>\n  );\n\n  return (\n    <View style={styles.container}>\n      <FlatList\n        data={logs}\n        keyExtractor={(i) => String(i.id)}\n        ListHeaderComponent={Header}\n        contentContainerStyle={{ padding: spacing.lg, paddingBottom: 110 }}\n        ItemSeparatorComponent={() => <View style={{ height: spacing.md }} />}\n        ListEmptyComponent={\n          loading ? null : (\n            <EmptyState\n              title=\"Sem registros\"\n              text=\"Registre seu peso e uma foto para acompanhar a evolução do seu corpo.\"\n              actionLabel=\"Novo registro\"\n              onAction={openNew}\n            />\n          )\n        }\n        renderItem={({ item }) => (\n          <Card style={styles.logRow} onPress={() => openEdit(item)}>\n            {item.photo ? (\n              <Image source={{ uri: item.photo }} style={styles.logPhoto} />\n            ) : (\n              <View style={[styles.logPhoto, styles.logPhotoEmpty]}>\n                <Ionicons name=\"person-outline\" size={24} color={colors.muted} />\n              </View>\n            )}\n            <View style={{ flex: 1, marginLeft: spacing.md }}>\n              <Text style={styles.logWeight}>{formatKg(item.weight)} kg</Text>\n              <Text style={styles.logDate}>{formatDate(item.date)}</Text>\n              {item.note ? (\n                <Text style={styles.logNote} numberOfLines={1}>\n                  {item.note}\n                </Text>\n              ) : null}\n            </View>\n            <IconButton name=\"trash-outline\" color={colors.danger} onPress={() => confirmDelete(item)} />\n          </Card>\n        )}\n      />\n\n      <Fab onPress={openNew} />\n\n      {/* ---------- Modal de criar / editar ---------- */}\n      <Modal visible={modalOpen} animationType=\"slide\" transparent onRequestClose={() => setModalOpen(false)}>\n        <KeyboardAvoidingView\n          behavior={Platform.OS === 'ios' ? 'padding' : undefined}\n          style={styles.modalBackdrop}\n        >\n          <View style={styles.modalSheet}>\n            <View style={styles.modalHeader}>\n              <Text style={styles.modalTitle}>{editingId ? 'Editar registro' : 'Novo registro'}</Text>\n              <IconButton name=\"close\" onPress={() => setModalOpen(false)} color={colors.text} />\n            </View>\n\n            <ScrollView keyboardShouldPersistTaps=\"handled\">\n              <Field\n                label=\"Peso (kg)\"\n                value={weight}\n                onChangeText={(t) => {\n                  setWeight(t);\n                  setError('');\n                }}\n                keyboardType=\"decimal-pad\"\n                placeholder=\"Ex.: 72,5\"\n                error={error}\n              />\n              <Field label=\"Anotação\" value={note} onChangeText={setNote} placeholder=\"Opcional\" />\n\n              <TouchableOpacity activeOpacity={0.85} onPress={() => chooseImage(setPhoto, [3, 4])} style={styles.photoBox}>\n                {photo ? (\n                  <Image source={{ uri: photo }} style={{ width: '100%', height: '100%' }} />\n                ) : (\n                  <View style={{ alignItems: 'center' }}>\n                    <Ionicons name=\"camera-outline\" size={32} color={colors.muted} />\n                    <Text style={{ color: colors.muted, marginTop: 6 }}>Foto de progresso (opcional)</Text>\n                  </View>\n                )}\n              </TouchableOpacity>\n              {photo ? (\n                <Button title=\"Remover foto\" variant=\"ghost\" onPress={() => setPhoto(null)} style={{ marginBottom: spacing.md }} />\n              ) : null}\n\n              <Button title=\"Salvar\" icon=\"checkmark\" onPress={save} />\n            </ScrollView>\n          </View>\n        </KeyboardAvoidingView>\n      </Modal>\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  summaryRow: { flexDirection: 'row' },\n  summaryCard: { flex: 1, alignItems: 'center' },\n  summaryLabel: { color: colors.muted, fontSize: 12, fontWeight: '600' },\n  summaryValue: { color: colors.text, fontSize: 22, fontWeight: '800', marginTop: 4 },\n  chartTitle: { color: colors.text, fontWeight: '700', marginBottom: spacing.md },\n  chart: { flexDirection: 'row', alignItems: 'flex-end', justifyContent: 'space-around', height: 170 },\n  barCol: { alignItems: 'center', flex: 1 },\n  bar: { width: 18, backgroundColor: colors.primary, borderRadius: 6, marginVertical: 4 },\n  barValue: { color: colors.text, fontSize: 10, fontWeight: '700' },\n  barLabel: { color: colors.muted, fontSize: 10 },\n  listTitle: { color: colors.text, fontSize: 18, fontWeight: '700', marginTop: spacing.lg, marginBottom: spacing.md },\n  logRow: { flexDirection: 'row', alignItems: 'center', padding: spacing.md },\n  logPhoto: { width: 56, height: 72, borderRadius: radius.sm },\n  logPhotoEmpty: { backgroundColor: colors.cardAlt, alignItems: 'center', justifyContent: 'center' },\n  logWeight: { color: colors.text, fontSize: 18, fontWeight: '800' },\n  logDate: { color: colors.muted, fontSize: 13, marginTop: 2 },\n  logNote: { color: colors.accent, fontSize: 13, marginTop: 4 },\n  modalBackdrop: { flex: 1, backgroundColor: 'rgba(0,0,0,0.6)', justifyContent: 'flex-end' },\n  modalSheet: {\n    backgroundColor: colors.bg,\n    borderTopLeftRadius: radius.lg,\n    borderTopRightRadius: radius.lg,\n    padding: spacing.lg,\n    maxHeight: '90%',\n  },\n  modalHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: spacing.lg },\n  modalTitle: { color: colors.text, fontSize: 20, fontWeight: '800' },\n  photoBox: {\n    height: 160,\n    borderRadius: radius.md,\n    overflow: 'hidden',\n    backgroundColor: colors.card,\n    borderWidth: 1,\n    borderColor: colors.border,\n    borderStyle: 'dashed',\n    alignItems: 'center',\n    justifyContent: 'center',\n    marginBottom: spacing.md,\n  },\n});\n","src/screens/SettingsScreen.js":"import React, { useState } from 'react';\nimport { Alert, ScrollView, StyleSheet, Switch, Text, Vibration, View } from 'react-native';\nimport { Accelerometer } from 'expo-sensors';\nimport { colors, spacing } from '../theme';\nimport { Button, Card, Chip, Field, SectionTitle, Stepper } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { resetAllData } from '../db/database';\n\nconst SENSITIVITY = [\n  { label: 'Alta', value: 1.5 },\n  { label: 'Média', value: 2.0 },\n  { label: 'Baixa', value: 2.6 },\n];\n\nexport default function SettingsScreen() {\n  const { settings, updateSetting, showToast, feedback } = useApp();\n  const [name, setName] = useState(settings.userName);\n  const [live, setLive] = useState(null); // leitura ao vivo do acelerômetro\n  const [testing, setTesting] = useState(false);\n  const subRef = React.useRef(null);\n\n  const saveName = () => {\n    const n = name.trim() || 'Atleta';\n    setName(n);\n    updateSetting('userName', n);\n    feedback.success();\n    showToast('Nome atualizado!');\n  };\n\n  // Teste do sensor: mostra a força medida em tempo real\n  const toggleSensorTest = async () => {\n    if (testing) {\n      if (subRef.current) subRef.current.remove();\n      subRef.current = null;\n      setTesting(false);\n      setLive(null);\n      return;\n    }\n    const ok = await Accelerometer.isAvailableAsync();\n    if (!ok) {\n      showToast('Este aparelho não tem acelerômetro', 'error');\n      return;\n    }\n    Accelerometer.setUpdateInterval(100);\n    subRef.current = Accelerometer.addListener(({ x, y, z }) =>\n      setLive(Math.sqrt(x * x + y * y + z * z))\n    );\n    setTesting(true);\n  };\n\n  React.useEffect(() => {\n    return () => {\n      if (subRef.current) subRef.current.remove();\n    };\n  }, []);\n\n  const testVibration = () => {\n    Vibration.vibrate([0, 300, 100, 300]);\n    showToast('Vibração testada');\n  };\n\n  const resetData = () => {\n    Alert.alert(\n      'Apagar todos os dados',\n      'Isso remove treinos, registros corporais e exercícios (os exercícios de exemplo serão recriados). Continuar?',\n      [\n        { text: 'Cancelar', style: 'cancel' },\n        {\n          text: 'Apagar tudo',\n          style: 'destructive',\n          onPress: async () => {\n            await resetAllData();\n            feedback.success();\n            showToast('Dados apagados');\n          },\n        },\n      ]\n    );\n  };\n\n  return (\n    <ScrollView\n      style={styles.container}\n      contentContainerStyle={{ padding: spacing.lg, paddingBottom: 60 }}\n      keyboardShouldPersistTaps=\"handled\"\n    >\n      <SectionTitle style={{ marginTop: 0 }}>Perfil</SectionTitle>\n      <Field label=\"Seu nome\" value={name} onChangeText={setName} onBlur={saveName} onSubmitEditing={saveName} />\n\n      <SectionTitle>Treino</SectionTitle>\n      <Card>\n        <View style={styles.row}>\n          <View style={{ flex: 1 }}>\n            <Text style={styles.title}>Meta semanal</Text>\n            <Text style={styles.desc}>Treinos por semana</Text>\n          </View>\n          <Stepper value={settings.weeklyGoal} onChange={(v) => updateSetting('weeklyGoal', v)} min={1} max={7} />\n        </View>\n        <View style={styles.divider} />\n        <View style={styles.row}>\n          <View style={{ flex: 1 }}>\n            <Text style={styles.title}>Descanso entre séries</Text>\n            <Text style={styles.desc}>Em segundos</Text>\n          </View>\n          <Stepper\n            value={settings.restSeconds}\n            onChange={(v) => updateSetting('restSeconds', v)}\n            min={15}\n            max={300}\n            step={15}\n          />\n        </View>\n      </Card>\n\n      <SectionTitle>Sensores e vibração</SectionTitle>\n      <Card>\n        <View style={styles.row}>\n          <View style={{ flex: 1, paddingRight: 12 }}>\n            <Text style={styles.title}>Contar repetições ao chacoalhar</Text>\n            <Text style={styles.desc}>Usa o acelerômetro. Segure o celular durante o movimento.</Text>\n          </View>\n          <Switch\n            value={settings.shake}\n            onValueChange={(v) => updateSetting('shake', v)}\n            trackColor={{ true: colors.primary, false: colors.border }}\n            thumbColor=\"#fff\"\n          />\n        </View>\n\n        <Text style={[styles.title, { marginTop: spacing.lg, marginBottom: spacing.sm }]}>Sensibilidade</Text>\n        <View style={{ flexDirection: 'row' }}>\n          {SENSITIVITY.map((s) => (\n            <Chip\n              key={s.label}\n              label={s.label}\n              active={settings.shakeThreshold === s.value}\n              onPress={() => updateSetting('shakeThreshold', s.value)}\n            />\n          ))}\n        </View>\n\n        <Button\n          title={testing ? 'Parar teste' : 'Testar acelerômetro'}\n          variant=\"ghost\"\n          icon=\"speedometer-outline\"\n          onPress={toggleSensorTest}\n          style={{ marginTop: spacing.md }}\n        />\n        {testing ? (\n          <Text style={styles.live}>\n            Força atual: {live ? live.toFixed(2) : '--'} g{'  '}\n            {live && live > settings.shakeThreshold ? '✅ contaria' : '(parado ≈ 1.00 g)'}\n          </Text>\n        ) : null}\n\n        <View style={styles.divider} />\n\n        <View style={styles.row}>\n          <View style={{ flex: 1, paddingRight: 12 }}>\n            <Text style={styles.title}>Vibração / feedback tátil</Text>\n            <Text style={styles.desc}>Vibra ao contar, concluir série e fim do descanso.</Text>\n          </View>\n          <Switch\n            value={settings.haptics}\n            onValueChange={(v) => updateSetting('haptics', v)}\n            trackColor={{ true: colors.primary, false: colors.border }}\n            thumbColor=\"#fff\"\n          />\n        </View>\n        <Button title=\"Testar vibração\" variant=\"ghost\" icon=\"radio-outline\" onPress={testVibration} style={{ marginTop: spacing.md }} />\n      </Card>\n\n      <SectionTitle>Dados</SectionTitle>\n      <Button title=\"Apagar todos os dados\" variant=\"danger\" icon=\"trash-outline\" onPress={resetData} />\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  row: { flexDirection: 'row', alignItems: 'center' },\n  title: { color: colors.text, fontSize: 16, fontWeight: '700' },\n  desc: { color: colors.muted, fontSize: 12, marginTop: 2 },\n  divider: { height: 1, backgroundColor: colors.border, marginVertical: spacing.lg },\n  live: { color: colors.accent, fontWeight: '700', marginTop: spacing.md, textAlign: 'center' },\n});\n","src/screens/WorkoutDetailScreen.js":"import React, { useCallback, useState } from 'react';\nimport { Alert, ScrollView, StyleSheet, Text, View } from 'react-native';\nimport { useFocusEffect } from '@react-navigation/native';\nimport { colors, radius, spacing } from '../theme';\nimport { Button, Card, Field, SectionTitle, StatBox } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { deleteWorkout, getWorkout, getWorkoutSets, updateWorkoutNotes } from '../db/database';\nimport { formatDateTime, formatDuration, formatKg } from '../utils/format';\n\nexport default function WorkoutDetailScreen({ route, navigation }) {\n  const { id } = route.params;\n  const { showToast, feedback } = useApp();\n  const [workout, setWorkout] = useState(null);\n  const [sets, setSets] = useState([]);\n  const [notes, setNotes] = useState('');\n\n  useFocusEffect(\n    useCallback(() => {\n      let active = true;\n      (async () => {\n        const w = await getWorkout(id);\n        const s = await getWorkoutSets(id);\n        if (!active) return;\n        setWorkout(w);\n        setSets(s);\n        setNotes(w ? w.notes || '' : '');\n      })();\n      return () => {\n        active = false;\n      };\n    }, [id])\n  );\n\n  if (!workout) {\n    return <View style={styles.container} />;\n  }\n\n  // agrupa as séries por exercício (mantendo a ordem em que foram feitas)\n  const groups = [];\n  sets.forEach((s) => {\n    let g = groups.find((x) => x.name === s.exercise_name);\n    if (!g) {\n      g = { name: s.exercise_name, sets: [] };\n      groups.push(g);\n    }\n    g.sets.push(s);\n  });\n\n  const saveNotes = async () => {\n    await updateWorkoutNotes(id, notes.trim());\n    feedback.success();\n    showToast('Anotação salva!');\n  };\n\n  const remove = () => {\n    Alert.alert('Excluir treino', 'Esta ação não pode ser desfeita.', [\n      { text: 'Cancelar', style: 'cancel' },\n      {\n        text: 'Excluir',\n        style: 'destructive',\n        onPress: async () => {\n          await deleteWorkout(id);\n          feedback.success();\n          showToast('Treino excluído');\n          navigation.goBack();\n        },\n      },\n    ]);\n  };\n\n  return (\n    <ScrollView\n      style={styles.container}\n      contentContainerStyle={{ padding: spacing.lg, paddingBottom: 60 }}\n      keyboardShouldPersistTaps=\"handled\"\n    >\n      <Text style={styles.date}>{formatDateTime(workout.started_at)}</Text>\n\n      <View style={styles.row}>\n        <StatBox icon=\"time-outline\" value={formatDuration(workout.duration_sec)} label=\"Duração\" color={colors.accent} />\n        <View style={{ width: spacing.sm }} />\n        <StatBox icon=\"repeat-outline\" value={workout.total_reps} label=\"Repetições\" color={colors.primary} />\n        <View style={{ width: spacing.sm }} />\n        <StatBox icon=\"barbell-outline\" value={formatKg(workout.volume)} label=\"Volume (kg)\" color={colors.warning} />\n      </View>\n\n      <SectionTitle>Exercícios realizados</SectionTitle>\n      {groups.map((g) => (\n        <Card key={g.name} style={{ marginBottom: spacing.md }}>\n          <Text style={styles.exName}>{g.name}</Text>\n          {g.sets.map((s) => (\n            <View key={s.id} style={styles.setRow}>\n              <Text style={styles.setNum}>Série {s.set_number}</Text>\n              <Text style={styles.setVal}>\n                {s.reps} reps × {formatKg(s.weight)} kg\n              </Text>\n            </View>\n          ))}\n        </Card>\n      ))}\n\n      <SectionTitle>Anotações</SectionTitle>\n      <Field value={notes} onChangeText={setNotes} placeholder=\"Como foi o treino? Sensações, dores, ajustes...\" multiline />\n      <Button title=\"Salvar anotação\" icon=\"save-outline\" variant=\"ghost\" onPress={saveNotes} />\n\n      <Button\n        title=\"Excluir treino\"\n        icon=\"trash-outline\"\n        variant=\"danger\"\n        onPress={remove}\n        style={{ marginTop: spacing.xl }}\n      />\n    </ScrollView>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  date: { color: colors.text, fontSize: 20, fontWeight: '800', marginBottom: spacing.lg },\n  row: { flexDirection: 'row' },\n  exName: { color: colors.text, fontSize: 17, fontWeight: '700', marginBottom: spacing.sm },\n  setRow: {\n    flexDirection: 'row',\n    justifyContent: 'space-between',\n    paddingVertical: 8,\n    borderTopWidth: 1,\n    borderTopColor: colors.border,\n  },\n  setNum: { color: colors.muted, fontWeight: '600' },\n  setVal: { color: colors.text, fontWeight: '700' },\n});\n","src/screens/WorkoutSetupScreen.js":"import React, { useCallback, useState } from 'react';\nimport { FlatList, Image, StyleSheet, Text, TouchableOpacity, View } from 'react-native';\nimport { useFocusEffect } from '@react-navigation/native';\nimport { Ionicons } from '@expo/vector-icons';\nimport { colors, GROUP_ICONS, radius, spacing } from '../theme';\nimport { Button, EmptyState } from '../components/UI';\nimport { useApp } from '../context/AppContext';\nimport { listExercises } from '../db/database';\n\nexport default function WorkoutSetupScreen({ navigation }) {\n  const { showToast, feedback } = useApp();\n  const [items, setItems] = useState([]);\n  const [selected, setSelected] = useState([]); // ids na ordem de escolha\n  const [loading, setLoading] = useState(true);\n\n  useFocusEffect(\n    useCallback(() => {\n      let active = true;\n      (async () => {\n        const list = await listExercises();\n        if (!active) return;\n        setItems(list);\n        // remove ids que foram excluídos\n        setSelected((sel) => sel.filter((id) => list.some((e) => e.id === id)));\n        setLoading(false);\n      })();\n      return () => {\n        active = false;\n      };\n    }, [])\n  );\n\n  const toggle = (id) => {\n    feedback.tap();\n    setSelected((sel) => (sel.includes(id) ? sel.filter((x) => x !== id) : [...sel, id]));\n  };\n\n  const totalSets = items\n    .filter((e) => selected.includes(e.id))\n    .reduce((acc, e) => acc + e.sets, 0);\n\n  const start = () => {\n    if (selected.length === 0) {\n      feedback.error();\n      showToast('Selecione pelo menos um exercício', 'error');\n      return;\n    }\n    navigation.navigate('TreinoAtivo', { ids: selected });\n  };\n\n  const renderItem = ({ item }) => {\n    const order = selected.indexOf(item.id);\n    const isSel = order >= 0;\n    return (\n      <TouchableOpacity\n        activeOpacity={0.85}\n        onPress={() => toggle(item.id)}\n        style={[styles.item, isSel && styles.itemSelected]}\n      >\n        {item.photo ? (\n          <Image source={{ uri: item.photo }} style={styles.thumb} />\n        ) : (\n          <View style={[styles.thumb, styles.thumbPlaceholder]}>\n            <Ionicons name={GROUP_ICONS[item.muscle_group] || 'barbell-outline'} size={22} color={colors.primary} />\n          </View>\n        )}\n        <View style={{ flex: 1, marginLeft: spacing.md }}>\n          <Text style={styles.name}>{item.name}</Text>\n          <Text style={styles.meta}>\n            {item.muscle_group} • {item.sets} × {item.reps}\n          </Text>\n        </View>\n        {isSel ? (\n          <View style={styles.badge}>\n            <Text style={styles.badgeText}>{order + 1}</Text>\n          </View>\n        ) : (\n          <Ionicons name=\"ellipse-outline\" size={26} color={colors.muted} />\n        )}\n      </TouchableOpacity>\n    );\n  };\n\n  return (\n    <View style={styles.container}>\n      <FlatList\n        data={items}\n        keyExtractor={(i) => String(i.id)}\n        renderItem={renderItem}\n        ListHeaderComponent={\n          items.length > 0 ? (\n            <View style={styles.header}>\n              <Text style={styles.title}>Monte seu treino</Text>\n              <Text style={styles.subtitle}>\n                Toque nos exercícios na ordem em que deseja fazê-los.\n              </Text>\n              <View style={styles.headerActions}>\n                <TouchableOpacity onPress={() => setSelected(items.map((i) => i.id))}>\n                  <Text style={styles.link}>Selecionar todos</Text>\n                </TouchableOpacity>\n                <TouchableOpacity onPress={() => setSelected([])}>\n                  <Text style={[styles.link, { color: colors.muted }]}>Limpar</Text>\n                </TouchableOpacity>\n              </View>\n            </View>\n          ) : null\n        }\n        contentContainerStyle={{ padding: spacing.lg, paddingBottom: 130 }}\n        ItemSeparatorComponent={() => <View style={{ height: spacing.sm }} />}\n        ListEmptyComponent={\n          loading ? null : (\n            <EmptyState\n              title=\"Sem exercícios\"\n              text=\"Cadastre exercícios na aba Exercícios para montar um treino.\"\n              actionLabel=\"Cadastrar exercício\"\n              onAction={() => navigation.navigate('FormExercicio')}\n            />\n          )\n        }\n      />\n\n      {items.length > 0 ? (\n        <View style={styles.footer}>\n          <Text style={styles.footerText}>\n            {selected.length} exercício(s) • {totalSets} série(s)\n          </Text>\n          <Button title=\"Começar\" icon=\"play\" variant=\"accent\" onPress={start} disabled={selected.length === 0} />\n        </View>\n      ) : null}\n    </View>\n  );\n}\n\nconst styles = StyleSheet.create({\n  container: { flex: 1, backgroundColor: colors.bg },\n  header: { marginBottom: spacing.md },\n  title: { color: colors.text, fontSize: 22, fontWeight: '800' },\n  subtitle: { color: colors.muted, marginTop: 4 },\n  headerActions: { flexDirection: 'row', justifyContent: 'space-between', marginTop: spacing.md },\n  link: { color: colors.accent, fontWeight: '700' },\n  item: {\n    flexDirection: 'row',\n    alignItems: 'center',\n    backgroundColor: colors.card,\n    padding: spacing.md,\n    borderRadius: radius.md,\n    borderWidth: 1,\n    borderColor: colors.border,\n  },\n  itemSelected: { borderColor: colors.primary, backgroundColor: colors.cardAlt },\n  thumb: { width: 52, height: 52, borderRadius: radius.sm },\n  thumbPlaceholder: { backgroundColor: colors.bg, alignItems: 'center', justifyContent: 'center' },\n  name: { color: colors.text, fontSize: 16, fontWeight: '700' },\n  meta: { color: colors.muted, fontSize: 13, marginTop: 2 },\n  badge: {\n    width: 28,\n    height: 28,\n    borderRadius: 14,\n    backgroundColor: colors.primary,\n    alignItems: 'center',\n    justifyContent: 'center',\n  },\n  badgeText: { color: '#fff', fontWeight: '800' },\n  footer: {\n    position: 'absolute',\n    left: 0,\n    right: 0,\n    bottom: 0,\n    padding: spacing.lg,\n    backgroundColor: colors.card,\n    borderTopWidth: 1,\n    borderTopColor: colors.border,\n  },\n  footerText: { color: colors.muted, textAlign: 'center', marginBottom: spacing.sm, fontWeight: '600' },\n});\n","src/theme.js":"export const colors = {\n  bg: '#0F1220',\n  card: '#1A1F36',\n  cardAlt: '#222845',\n  primary: '#6C63FF',\n  accent: '#00D4AA',\n  danger: '#FF5C7A',\n  warning: '#FFB84D',\n  text: '#FFFFFF',\n  muted: '#9AA3C7',\n  border: '#2A3050',\n};\n\nexport const spacing = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24 };\nexport const radius = { sm: 8, md: 14, lg: 20 };\n\nexport const GROUPS = ['Peito', 'Costas', 'Pernas', 'Ombros', 'Braços', 'Abdômen', 'Cardio'];\n\nexport const GROUP_ICONS = {\n  Peito: 'fitness-outline',\n  Costas: 'body-outline',\n  Pernas: 'walk-outline',\n  Ombros: 'barbell-outline',\n  'Braços': 'hand-left-outline',\n  'Abdômen': 'flame-outline',\n  Cardio: 'heart-outline',\n};\n","src/utils/format.js":"export const pad = (n) => String(n).padStart(2, '0');\n\nexport function formatDuration(totalSec) {\n  const sec = Math.max(0, Math.floor(totalSec || 0));\n  const h = Math.floor(sec / 3600);\n  const m = Math.floor((sec % 3600) / 60);\n  const s = sec % 60;\n  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;\n}\n\nexport function formatDate(iso) {\n  const d = new Date(iso);\n  return `${pad(d.getDate())}/${pad(d.getMonth() + 1)}/${d.getFullYear()}`;\n}\n\nexport function formatDateTime(iso) {\n  const d = new Date(iso);\n  return `${formatDate(iso)} às ${pad(d.getHours())}:${pad(d.getMinutes())}`;\n}\n\n// Aceita \"12,5\" ou \"12.5\". Retorna NaN se inválido.\nexport function parseNumber(text) {\n  const n = parseFloat(String(text).replace(',', '.'));\n  return Number.isNaN(n) ? NaN : n;\n}\n\nexport function formatKg(n) {\n  const v = Number(n) || 0;\n  return Number.isInteger(v) ? `${v}` : v.toFixed(1).replace('.', ',');\n}\n\nexport function dayKey(dateLike) {\n  const d = new Date(dateLike);\n  return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;\n}\n\nexport function greeting() {\n  const h = new Date().getHours();\n  if (h < 12) return 'Bom dia';\n  if (h < 18) return 'Boa tarde';\n  return 'Boa noite';\n}\n","src/utils/images.js":"import * as ImagePicker from 'expo-image-picker';\nimport { Alert } from 'react-native';\n\n// Abre câmera ou galeria e devolve a imagem como data-URI (base64),\n// assim ela fica guardada dentro do próprio banco SQLite.\nexport async function pickImage(source, aspect = [4, 3]) {\n  const perm =\n    source === 'camera'\n      ? await ImagePicker.requestCameraPermissionsAsync()\n      : await ImagePicker.requestMediaLibraryPermissionsAsync();\n\n  if (!perm.granted) {\n    Alert.alert(\n      'Permissão necessária',\n      source === 'camera'\n        ? 'Permita o acesso à câmera nas configurações do celular.'\n        : 'Permita o acesso às fotos nas configurações do celular.'\n    );\n    return null;\n  }\n\n  const options = {\n    mediaTypes: ['images'],\n    allowsEditing: true,\n    aspect,\n    quality: 0.4,\n    base64: true,\n  };\n\n  const result =\n    source === 'camera'\n      ? await ImagePicker.launchCameraAsync(options)\n      : await ImagePicker.launchImageLibraryAsync(options);\n\n  if (result.canceled || !result.assets || result.assets.length === 0) return null;\n  const asset = result.assets[0];\n  return asset.base64 ? `data:image/jpeg;base64,${asset.base64}` : asset.uri;\n}\n\nexport function chooseImage(onPicked, aspect = [4, 3]) {\n  Alert.alert('Adicionar foto', 'Escolha a origem da imagem', [\n    {\n      text: 'Câmera',\n      onPress: async () => {\n        const uri = await pickImage('camera', aspect);\n        if (uri) onPicked(uri);\n      },\n    },\n    {\n      text: 'Galeria',\n      onPress: async () => {\n        const uri = await pickImage('gallery', aspect);\n        if (uri) onPicked(uri);\n      },\n    },\n    { text: 'Cancelar', style: 'cancel' },\n  ]);\n}\n","App.js":"import React from 'react';\nimport { StatusBar } from 'expo-status-bar';\nimport { SafeAreaProvider } from 'react-native-safe-area-context';\nimport { AppProvider } from './src/context/AppContext';\nimport Navigation from './src/navigation';\n\nexport default function App() {\n  return (\n    <SafeAreaProvider>\n      <StatusBar style=\"light\" />\n      <AppProvider>\n        <Navigation />\n      </AppProvider>\n    </SafeAreaProvider>\n  );\n}\n","README.md":"# 🏋️ GymLog — Diário de Treinos com Sensores\n\n> Projeto da disciplina **CCP150 – Desenvolvimento de Aplicativos Móveis** (FEI) · Prof. Vinicius\n> Autor: **_<SEU NOME COMPLETO>_** · RA: **_<SEU RA>_**\n\nAplicativo móvel feito com **React Native (Expo)** para registrar treinos de musculação, contar repetições usando o **acelerômetro** do celular, acompanhar a evolução corporal e visualizar estatísticas.\n\n---\n\n## 1. Visão Geral e Requisitos\n\n**Motivação:** muita gente anota treino em papel ou planilha e perde o histórico. Quis criar um app simples que guie o treino em tempo real (séries, descanso, cronômetro) e guarde tudo localmente.\n\n**Objetivo:** permitir montar treinos, executá-los com ajuda de sensores/vibração e acompanhar o progresso.\n\n### Requisitos do projeto × onde foram atendidos\n\n| Requisito | Como foi atendido |\n|---|---|\n| Mínimo de 6 telas distintas | **9 telas**: Início, Exercícios, Formulário de Exercício, Montar Treino, Treino Ativo, Histórico, Detalhe do Treino, Progresso, Configurações |\n| Navegação com React Navigation | **Bottom Tabs** (5 abas) + **Native Stack** (telas de formulário, treino e detalhes) |\n| Imagens | Banner e ilustrações locais (`assets/`), fotos dos exercícios e fotos de progresso (câmera/galeria) |\n| Interface e UX | Tema escuro consistente, layout organizado, alinhamento e espaçamento padronizados (`src/theme.js`), componentes reutilizáveis (`src/components/UI.js`) |\n| Feedback ao usuário | Toasts animados, alertas de confirmação, validação com mensagens de erro nos campos, vibração, estados vazios ilustrados |\n| Banco de dados + CRUD completo | **SQLite** (`expo-sqlite`): salvar, recuperar, atualizar e remover em exercícios, treinos e registros corporais |\n| Sensor / atuador | **Acelerômetro** (chacoalhar = +1 repetição) e **vibração/haptics** (confirmações e fim do descanso) |\n\n> Telas de login/cadastro não foram implementadas, conforme as considerações do projeto.\n\n---\n\n## 2. Tecnologias Utilizadas\n\n- **React Native** + **Expo** (JavaScript)\n- **React Navigation** (`native-stack`, `bottom-tabs`)\n- **expo-sqlite** — banco de dados local\n- **expo-sensors** — acelerômetro\n- **expo-haptics** e `Vibration` — atuador (vibração)\n- **expo-image-picker** — câmera e galeria\n- **expo-keep-awake** — mantém a tela ligada durante o treino\n- **@expo/vector-icons** (Ionicons)\n- **react-native-safe-area-context**, **react-native-screens**\n\n### Estrutura de pastas\n\n```\nApp.js\nassets/               imagens locais\nsrc/\n  components/UI.js    botões, cards, campos, chips, steppers...\n  context/AppContext.js  configurações globais, toast e feedback tátil\n  db/database.js      criação das tabelas e todas as operações CRUD\n  navigation/index.js tabs + stack\n  screens/            as 9 telas\n  utils/              formatação e seleção de imagens\n  theme.js            cores, espaçamentos, grupos musculares\n```\n\n### Modelo do banco de dados\n\n- `exercises` — id, nome, grupo muscular, séries, repetições, carga, observações, foto\n- `workouts` — id, data/hora de início, duração, anotações\n- `workout_sets` — séries realizadas (FK → `workouts`, exclusão em cascata)\n- `body_logs` — peso, anotação e foto de progresso\n- `settings` — chave/valor (nome, meta semanal, descanso, sensor, vibração)\n\n---\n\n## 3. Funcionalidades\n\n- **Início:** saudação, meta semanal com barra de progresso, resumo geral (treinos, repetições, minutos), gráfico dos últimos 7 dias e atalho para o último treino.\n- **Exercícios (CRUD):** lista com busca e filtro por grupo muscular; criar, editar e excluir exercícios, com foto (câmera ou galeria) e validação dos campos.\n- **Montar treino:** escolha dos exercícios na ordem desejada, com contagem total de séries.\n- **Treino ativo:**\n  - cronômetro do treino e barra de progresso entre exercícios;\n  - **chacoalhar o celular conta +1 repetição** (acelerômetro com tempo mínimo entre detecções para evitar contagens duplas); também há botões `−` / `+`;\n  - ajuste de carga por série;\n  - **timer de descanso** automático entre séries, com `+15s` e `Pular`; ao terminar, o celular **vibra**;\n  - pular exercício, finalizar antes da hora e confirmação ao tentar sair;\n  - tela sempre acesa.\n- **Histórico:** todos os treinos com volume (kg), repetições e duração; excluir treino.\n- **Detalhe do treino:** séries agrupadas por exercício, **anotações editáveis** (Update) e exclusão.\n- **Progresso (CRUD):** registro de peso com foto, gráfico de evolução, variação total; editar e excluir registros.\n- **Configurações:** nome, meta semanal, tempo de descanso, ligar/desligar sensor, sensibilidade, **teste ao vivo do acelerômetro**, vibração e apagar dados.\n\n### Complexidade técnica\n\n- Consultas SQL agregadas (`SUM`, `COUNT DISTINCT`, subconsultas) para volume e estatísticas.\n- Transação (`withTransactionAsync`) ao salvar um treino com várias séries.\n- Detecção de movimento pela magnitude do vetor de aceleração `√(x²+y²+z²)` com limiar configurável e debounce.\n- Máquina de estados do treino (exercício → série → descanso) com cronômetro baseado em timestamps (não acumula erro).\n- Interceptação do botão voltar (`beforeRemove`) para não perder um treino em andamento.\n- Gráficos de barras desenhados à mão com `View` (sem biblioteca extra).\n- Imagens salvas em base64 dentro do próprio SQLite (não dependem de arquivos temporários).\n\n---\n\n## 4. Demonstração\n\n> 📹 **Inclua aqui um GIF ou vídeo do app funcionando** (ex.: `docs/demo.gif`).\n\n```md\n![Demonstração](docs/demo.gif)\n```\n\n### Telas\n\n| Início | Exercícios | Treino ativo |\n|---|---|---|\n| ![](docs/home.png) | ![](docs/exercicios.png) | ![](docs/treino.png) |\n\n| Histórico | Progresso | Configurações |\n|---|---|---|\n| ![](docs/historico.png) | ![](docs/progresso.png) | ![](docs/config.png) |\n\n---\n\n## 5. Instalação e Execução\n\n**Pré-requisitos:** [Node.js LTS](https://nodejs.org), Git e o app **Expo Go** instalado no celular (Android/iOS).\n\n```bash\n# 1) clonar o repositório\ngit clone <URL-DO-SEU-REPOSITORIO>\ncd GymLog\n\n# 2) instalar dependências\nnpm install\n\n# 3) iniciar o projeto\nnpx expo start\n```\n\nEscaneie o QR Code com o **Expo Go** (Android) ou com a câmera (iOS). Celular e computador devem estar na **mesma rede Wi-Fi**.\n\n> ⚠️ O acelerômetro e a vibração **não funcionam em emulador de computador/web** — teste em um celular real.\n\n---\n\n## 6. Aprendizados e Próximos Passos\n\n> ✍️ **Escreva aqui, com suas palavras,** o que você aprendeu (ex.: uso de SQLite no Expo, leitura de sensores, React Navigation, organização em componentes) e as dificuldades enfrentadas (ex.: calibrar o limiar do acelerômetro, controlar o ciclo de vida de listeners).\n\n**Próximos passos possíveis:**\n- Sincronizar os dados na nuvem (Firebase) e adicionar login.\n- Gráficos por exercício (evolução de carga).\n- Notificações locais para lembrar dos treinos.\n- Exportar histórico em CSV.\n- Treinos pré-montados (templates) e timer em segundo plano.\n"};
const IMAGES = {"assets/banner.png":"","assets/empty.png":""};

const base = process.cwd();
if (!fs.existsSync(path.join(base, 'package.json'))) {
  console.error('\nERRO: package.json nao encontrado.');
  console.error('Coloque o setup.js dentro da pasta GymLogApp (a que tem o package.json) e rode de novo.\n');
  process.exit(1);
}

function write(rel, data, encoding) {
  const full = path.join(base, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, data, encoding);
  console.log('  criado: ' + rel);
}

console.log('\n[1/2] Criando arquivos do GymLog...');
for (const rel of Object.keys(FILES)) write(rel, FILES[rel], 'utf8');
for (const rel of Object.keys(IMAGES)) write(rel, Buffer.from(IMAGES[rel], 'base64'));

console.log('\n[2/2] Instalando bibliotecas (pode demorar alguns minutos)...\n');
const libs = [
  '@react-navigation/native', '@react-navigation/native-stack', '@react-navigation/bottom-tabs',
  'react-native-screens', 'react-native-safe-area-context',
  'expo-sqlite', 'expo-sensors', 'expo-haptics', 'expo-image-picker', 'expo-keep-awake',
  '@expo/vector-icons',
].join(' ');
try {
  execSync('npx expo install ' + libs, { stdio: 'inherit' });
  console.log('\nTUDO PRONTO! Agora rode:  npx expo start\n');
} catch (e) {
  console.error('\nOs arquivos foram criados, mas a instalacao das bibliotecas falhou.');
  console.error('Rode manualmente:  npx expo install ' + libs + '\n');
  process.exit(1);
}
